-- Reproducible selected-subject quest lessons and scored-bank topic groupings.
begin;
insert into public.subject_quest_catalogue select * from jsonb_populate_recordset(null::public.subject_quest_catalogue,'[{"course_id":"gcse-maths","topic_id":"gcse-maths-percentages","course_title":"GCSE Mathematics","title":"Percentages and percentage change","content":{"summary":"Find percentages of amounts, increase and decrease by a percentage, and work out percentage change.","objectives":["Find a percentage of an amount with and without a calculator","Use multipliers for percentage increase and decrease","Calculate percentage change and reverse percentages"],"explanation":["Per cent means ''out of 100''. 35% is 35/100 = 0.35. Converting percentages to decimals lets you use a single multiplication.","Without a calculator, build from easy pieces: 10% is ÷10, 5% is half of 10%, 1% is ÷100. For example 15% of 80 = 10% (8) + 5% (4) = 12.","A multiplier combines the original amount and the change. An increase of 12% means you keep 100% and add 12%, so multiply by 1.12. A decrease of 12% leaves 88%, so multiply by 0.88.","Percentage change = (change ÷ original) × 100. Always divide by the original value, not the new one.","Reverse percentages work backwards from the new value: if a price after a 20% increase is £60, then 1.2 × original = 60, so original = 60 ÷ 1.2 = £50."],"workedExample":{"question":"A jacket costs £64. In a sale it is reduced by 15%. What is the sale price?","steps":["A 15% decrease leaves 85% of the price.","Multiplier = 0.85.","£64 × 0.85 = £54.40."],"answer":"£54.40"},"keyTerms":[{"term":"Multiplier","definition":"The decimal you multiply by to apply a percentage change in one step, e.g. 1.05 for a 5% increase."},{"term":"Percentage change","definition":"(Change ÷ original value) × 100."},{"term":"Reverse percentage","definition":"Finding the original amount when you know the value after a percentage change."},{"term":"Compound interest","definition":"Interest calculated on the original amount plus interest already added; use multiplier to the power of the number of periods."}],"misconceptions":[{"wrong":"To undo a 20% increase, take off 20% of the new price.","right":"Divide by the multiplier (1.2). Taking 20% of the new, larger price removes too much."},{"wrong":"Percentage change divides by the new value.","right":"Always divide the change by the original value."}],"retrieval":[{"q":"What multiplier gives a 7% decrease?","a":"0.93"},{"q":"What is 15% of 80?","a":"12"},{"q":"A value rises from 40 to 50. What is the percentage increase?","a":"10 ÷ 40 × 100 = 25%"}],"specRefs":[{"board":"AQA","code":"8300","section":"R9 percentages; N12, R16 compound interest","url":"https://www.aqa.org.uk/subjects/mathematics/gcse/mathematics-8300/specification"}],"route":"gcse","subject":"Mathematics"},"question_keys":["gcse-maths-percentages:pc1","gcse-maths-percentages:pc2","gcse-maths-percentages:pc3","gcse-maths-percentages:pc4"],"version":"1.0"},{"course_id":"gcse-maths","topic_id":"gcse-maths-linear-equations","course_title":"GCSE Mathematics","title":"Solving linear equations","content":{"summary":"Solve equations with unknowns on one or both sides, including brackets and fractions.","objectives":["Use inverse operations to solve one- and two-step equations","Solve equations with unknowns on both sides and with brackets","Form and solve an equation from a word problem"],"explanation":["An equation is balanced: whatever you do to one side you must do to the other. The aim is to get the unknown on its own.","Undo operations in reverse order. For 3x + 5 = 20, subtract 5 first (3x = 15), then divide by 3 (x = 5).","With unknowns on both sides, collect the unknowns on the side with the larger coefficient to avoid negatives, then solve as normal.","Expand brackets first, or divide both sides by the number outside the bracket when that gives whole numbers.","Check your answer by substituting it back into the original equation."],"workedExample":{"question":"Solve 5x − 4 = 2x + 11.","steps":["Subtract 2x from both sides: 3x − 4 = 11.","Add 4 to both sides: 3x = 15.","Divide by 3: x = 5.","Check: 5(5) − 4 = 21 and 2(5) + 11 = 21 ✓"],"answer":"x = 5"},"keyTerms":[{"term":"Equation","definition":"A statement that two expressions are equal, which is true only for particular value(s) of the unknown."},{"term":"Inverse operation","definition":"The operation that undoes another, e.g. subtraction undoes addition."},{"term":"Coefficient","definition":"The number multiplying a variable, e.g. 3 in 3x."},{"term":"Expand","definition":"Multiply out brackets, e.g. 2(x + 3) = 2x + 6."}],"misconceptions":[{"wrong":"2(x + 3) = 2x + 3","right":"Multiply every term inside: 2(x + 3) = 2x + 6."},{"wrong":"If 4x = 12 then x = 12 − 4.","right":"4x means 4 × x, so divide: x = 3."}],"retrieval":[{"q":"Solve 2x + 7 = 19.","a":"x = 6"},{"q":"Solve 3(x − 2) = 15.","a":"x = 7"},{"q":"What should you do first to solve 7x + 1 = 4x + 13?","a":"Subtract 4x from both sides (gives 3x + 1 = 13)."}],"specRefs":[{"board":"AQA","code":"8300","section":"A17 linear equations","url":"https://www.aqa.org.uk/subjects/mathematics/gcse/mathematics-8300/specification"}],"route":"gcse","subject":"Mathematics"},"question_keys":["gcse-maths-linear-equations:le1","gcse-maths-linear-equations:le2","gcse-maths-linear-equations:le3"],"version":"1.0"},{"course_id":"gcse-english-language","topic_id":"gcse-englang-language-analysis","course_title":"GCSE English Language","title":"Analysing language","content":{"summary":"Explain how writers use words, phrases and techniques to create effects on the reader.","objectives":["Select short, precise quotations","Identify language features using accurate terminology","Explain the effect of language choices on the reader"],"explanation":["Examiners reward explanation of effect more than spotting techniques. Naming a metaphor earns little unless you explain what it suggests and why the writer chose it.","Use short quotations, often a single word or phrase, and zoom in on connotations: what ideas, feelings or images does the word bring to mind?","A useful structure is: point about the writer''s method → embedded quotation → explanation of effect → link to the writer''s wider purpose.","Consider word classes too: a verb can show how something moves or acts, adjectives can build atmosphere, and adverbs can reveal attitude."],"workedExample":{"question":"Analyse: ''The wind clawed at the windows, desperate to get in.''","steps":["Method: personification. The wind is given a human feeling (''desperate''), and the verb ''clawed'' adds animal-like imagery.","Zoom in: ''clawed'' suggests sharp, violent, animal movement.","Effect: the weather feels threatening and alive; ''desperate'' adds urgency and makes the house feel under attack.","Purpose: builds tension and a sense of danger for the reader."],"answer":"A strong answer links the verb ''clawed'' and the adjective ''desperate'' to a mood of threat and tension."},"keyTerms":[{"term":"Connotation","definition":"An idea or feeling a word suggests beyond its literal meaning."},{"term":"Personification","definition":"Giving human qualities to something non-human."},{"term":"Semantic field","definition":"A group of words linked by a common topic, e.g. words linked to war."},{"term":"Embedded quotation","definition":"A short quotation woven into your own sentence."}],"misconceptions":[{"wrong":"''This makes the reader want to read on'' is a good explanation.","right":"Be specific: say what the reader feels or imagines, and why that word creates it."},{"wrong":"Long quotations show more evidence.","right":"Short, precise quotations let you analyse individual word choices."}],"retrieval":[{"q":"What is a connotation?","a":"An idea or feeling associated with a word beyond its literal meaning."},{"q":"Name the four parts of a strong analytical paragraph.","a":"Method, quotation, effect, link to purpose."},{"q":"Why is naming a technique not enough?","a":"Marks are for explaining the effect of the choice, not labelling it."}],"specRefs":[{"board":"AQA","code":"8700","section":"AO2 — Paper 1 and Paper 2, Section A (Reading)","url":"https://www.aqa.org.uk/subjects/english/gcse/english-language-8700/specification"}],"route":"gcse","subject":"English Language"},"question_keys":["gcse-englang-language-analysis:la1","gcse-englang-language-analysis:la2","gcse-englang-language-analysis:la3"],"version":"1.1"},{"course_id":"gcse-english-literature","topic_id":"gcse-englit-essay-writing","course_title":"GCSE English Literature","title":"Writing a literature essay","content":{"summary":"Plan and write a clear, analytical essay on a set text in timed conditions.","objectives":["Build an argument that answers the exact question","Use well-chosen references to the text","Weave in context where it deepens the argument"],"explanation":["Start with a thesis: one or two sentences that answer the question directly. Each paragraph should then develop one part of that argument.","Use references you know well. Short memorised quotations are more flexible than long ones, and close references (describing a moment precisely) also count as evidence.","Analyse the writer''s methods (language, structure and form) and explain how they shape meaning. Write about the writer as someone making deliberate choices.","Context is strongest when it explains why a writer might present an idea in a certain way, rather than as a separate history paragraph.","Spend a few minutes planning. A quick plan helps you stay focused and cover the whole text, not just the extract."],"workedExample":null,"keyTerms":[{"term":"Thesis","definition":"Your overall argument in answer to the question."},{"term":"Context","definition":"Historical, social or literary background that helps explain a text''s ideas."},{"term":"Form","definition":"The type of text, e.g. play, novel, sonnet, and how that shapes meaning."},{"term":"Structure","definition":"How a text is organised and ordered, and the effect of that order."}],"misconceptions":[{"wrong":"Retelling the plot shows good knowledge.","right":"Only use plot to support an analytical point that answers the question."},{"wrong":"Context should be a separate paragraph.","right":"Integrate context where it explains the writer''s choices."}],"retrieval":[{"q":"What is a thesis statement?","a":"A direct, arguable answer to the essay question."},{"q":"Name the three kinds of writer''s methods.","a":"Language, structure and form."},{"q":"When is context most useful?","a":"When it helps explain why the writer presents ideas in a particular way."}],"specRefs":[{"board":"AQA","code":"8702","section":"AO1–AO4, Papers 1 and 2","url":"https://www.aqa.org.uk/subjects/english/gcse/english-literature-8702/specification"}],"route":"gcse","subject":"English Literature"},"question_keys":["gcse-englit-essay-writing:ee1","gcse-englit-essay-writing:ee2"],"version":"1.0"},{"course_id":"gcse-biology","topic_id":"gcse-bio-cells","course_title":"GCSE Biology","title":"Cell structure","content":{"summary":"Compare animal, plant and bacterial cells and the jobs of their parts.","objectives":["Name the main structures in animal and plant cells and state their functions","Compare eukaryotic and prokaryotic cells","Use magnification = image size ÷ actual size"],"explanation":["Animal and plant cells are eukaryotic: their genetic material is enclosed in a nucleus. Both have a nucleus, cytoplasm, cell membrane, mitochondria and ribosomes.","Plant cells also usually have a cellulose cell wall for support, chloroplasts for photosynthesis and a permanent vacuole containing cell sap.","Bacterial cells are prokaryotic. They are much smaller, have no nucleus (their DNA is a single loop in the cytoplasm) and may contain small rings of DNA called plasmids.","Magnification = image size ÷ actual size. Convert units first so both sizes use the same unit (1 mm = 1000 µm)."],"workedExample":{"question":"A cell drawing is 40 mm long. The real cell is 0.08 mm long. What is the magnification?","steps":["Magnification = image ÷ actual.","40 ÷ 0.08 = 500."],"answer":"×500"},"keyTerms":[{"term":"Nucleus","definition":"Contains genetic material and controls the activities of the cell."},{"term":"Mitochondria","definition":"Where most aerobic respiration reactions take place, releasing energy."},{"term":"Ribosome","definition":"Site of protein synthesis."},{"term":"Chloroplast","definition":"Contains chlorophyll; where photosynthesis takes place."},{"term":"Plasmid","definition":"A small ring of DNA found in many bacterial cells."}],"misconceptions":[{"wrong":"Mitochondria make energy.","right":"Energy cannot be made. Respiration in mitochondria releases energy stored in glucose."},{"wrong":"All plant cells have chloroplasts.","right":"Cells not exposed to light, such as root hair cells, do not have chloroplasts."}],"retrieval":[{"q":"Name three structures found in plant cells but not animal cells.","a":"Cell wall, chloroplasts, permanent vacuole."},{"q":"Where is the DNA in a bacterial cell?","a":"A single loop in the cytoplasm, plus plasmids."},{"q":"Write the magnification equation.","a":"Magnification = image size ÷ actual size."}],"specRefs":[{"board":"AQA","code":"8461","section":"4.1.1 Cell structure","url":"https://www.aqa.org.uk/subjects/biology/gcse/biology-8461/specification"}],"route":"gcse","subject":"Biology"},"question_keys":["gcse-bio-cells:ce1","gcse-bio-cells:ce2","gcse-bio-cells:ce3","gcse-bio-cells:ce4"],"version":"1.0"},{"course_id":"gcse-biology","topic_id":"gcse-bio-enzymes","course_title":"GCSE Biology","title":"Enzymes","content":{"summary":"How enzymes speed up reactions and what affects their activity.","objectives":["Describe enzymes as biological catalysts","Explain enzyme action using the lock and key model","Explain the effect of temperature and pH on enzyme activity"],"explanation":["Enzymes are proteins that act as biological catalysts: they speed up reactions without being used up.","Each enzyme has an active site with a specific shape. Only a substrate with a complementary shape fits, forming an enzyme–substrate complex. This is the lock and key model.","As temperature rises, particles move faster and collide more often, so the rate increases up to an optimum. Above the optimum, bonds holding the enzyme''s shape break, the active site changes shape and the enzyme is denatured.","Each enzyme also has an optimum pH. Moving too far from it can change the active site''s shape and denature the enzyme."],"workedExample":null,"keyTerms":[{"term":"Catalyst","definition":"A substance that speeds up a reaction without being used up."},{"term":"Active site","definition":"The region of an enzyme where the substrate binds."},{"term":"Substrate","definition":"The molecule an enzyme acts on."},{"term":"Denatured","definition":"Permanently changed in shape so the active site no longer fits the substrate."}],"misconceptions":[{"wrong":"High temperatures kill enzymes.","right":"Enzymes are molecules, not living things. They are denatured, not killed."},{"wrong":"Low temperatures denature enzymes.","right":"Low temperatures slow reactions because of fewer collisions, but the active site is not permanently changed."}],"retrieval":[{"q":"What type of molecule is an enzyme?","a":"A protein."},{"q":"What happens to the active site when an enzyme is denatured?","a":"It changes shape so the substrate no longer fits."},{"q":"Name the model that explains enzyme specificity.","a":"The lock and key model."}],"specRefs":[{"board":"AQA","code":"8461","section":"4.2.2.1 The human digestive system","url":"https://www.aqa.org.uk/subjects/biology/gcse/biology-8461/specification"}],"route":"gcse","subject":"Biology"},"question_keys":["gcse-bio-enzymes:en1","gcse-bio-enzymes:en2"],"version":"1.0"},{"course_id":"gcse-chemistry","topic_id":"gcse-chem-atomic-structure","course_title":"GCSE Chemistry","title":"Atomic structure","content":{"summary":"Protons, neutrons and electrons, atomic and mass numbers, isotopes and electron configuration.","objectives":["Describe the structure of an atom and the relative charge and mass of subatomic particles","Use atomic number and mass number to work out numbers of particles","Explain what isotopes are and write simple electron configurations"],"explanation":["An atom has a tiny central nucleus containing protons and neutrons, surrounded by electrons in shells (energy levels). Most of an atom''s mass is in the nucleus.","Relative charges: proton +1, neutron 0, electron −1. Relative masses: proton 1, neutron 1, electron very small (about 1/2000).","Atomic number = number of protons (and electrons in a neutral atom). Mass number = protons + neutrons, so neutrons = mass number − atomic number.","Isotopes are atoms of the same element with the same number of protons but different numbers of neutrons.","For the first 20 elements, the first shell holds up to 2 electrons and the second and third shells hold up to 8 each, e.g. sodium (11 electrons) is 2,8,1 and calcium (20 electrons) is 2,8,8,2."],"workedExample":{"question":"Chlorine-37 has atomic number 17. How many protons, neutrons and electrons does a chlorine-37 atom have?","steps":["Protons = atomic number = 17.","Electrons = protons in a neutral atom = 17.","Neutrons = 37 − 17 = 20."],"answer":"17 protons, 20 neutrons, 17 electrons"},"keyTerms":[{"term":"Atomic number","definition":"The number of protons in the nucleus of an atom."},{"term":"Mass number","definition":"The total number of protons and neutrons in an atom."},{"term":"Isotope","definition":"Atoms of the same element with different numbers of neutrons."},{"term":"Electron shell","definition":"An energy level that electrons occupy around the nucleus."}],"misconceptions":[{"wrong":"Isotopes have different numbers of protons.","right":"Isotopes have the same number of protons; only the neutron number differs."},{"wrong":"Electrons are in the nucleus.","right":"Electrons occupy shells around the nucleus."}],"retrieval":[{"q":"What is the charge of a neutron?","a":"0 (no charge)."},{"q":"How do you calculate the number of neutrons?","a":"Mass number − atomic number."},{"q":"Write the electron configuration of magnesium (12 electrons).","a":"2,8,2"}],"specRefs":[{"board":"AQA","code":"8462","section":"4.1.1 A simple model of the atom","url":"https://www.aqa.org.uk/subjects/chemistry/gcse/chemistry-8462/specification"}],"route":"gcse","subject":"Chemistry"},"question_keys":["gcse-chem-atomic-structure:at1","gcse-chem-atomic-structure:at2","gcse-chem-atomic-structure:at3"],"version":"1.1"},{"course_id":"gcse-chemistry","topic_id":"gcse-chem-bonding","course_title":"GCSE Chemistry","title":"Ionic and covalent bonding","content":{"summary":"How atoms bond by transferring or sharing electrons, and how structure affects properties.","objectives":["Describe ionic bonding as electron transfer between metals and non-metals","Describe covalent bonding as sharing pairs of electrons between non-metals","Link structure to melting point and electrical conductivity"],"explanation":["Ionic bonding happens between metals and non-metals. Metal atoms lose electrons to become positive ions; non-metal atoms gain electrons to become negative ions. Oppositely charged ions attract strongly.","Ionic compounds form giant lattices with high melting points. They conduct electricity when molten or dissolved because the ions can move.","Covalent bonding happens between non-metal atoms, which share pairs of electrons.","Simple molecular substances (like water or carbon dioxide) have strong covalent bonds within molecules but weak intermolecular forces between them, so they have low melting and boiling points.","Giant covalent structures (like diamond and silicon dioxide) have many strong covalent bonds and very high melting points."],"workedExample":null,"keyTerms":[{"term":"Ion","definition":"An atom or group of atoms with an electric charge from losing or gaining electrons."},{"term":"Covalent bond","definition":"A shared pair of electrons between two atoms."},{"term":"Intermolecular forces","definition":"Weak forces of attraction between molecules."},{"term":"Giant lattice","definition":"A regular three-dimensional arrangement of a very large number of particles."}],"misconceptions":[{"wrong":"Boiling water breaks covalent bonds.","right":"Boiling overcomes weak intermolecular forces; the O–H covalent bonds stay intact."},{"wrong":"Solid ionic compounds conduct electricity.","right":"In a solid the ions are fixed in place; they must be molten or dissolved to conduct."}],"retrieval":[{"q":"What type of bonding forms between a metal and a non-metal?","a":"Ionic bonding."},{"q":"Why does sodium chloride conduct when molten?","a":"Its ions are free to move and carry charge."},{"q":"Why do simple molecular substances have low boiling points?","a":"Only weak intermolecular forces need to be overcome."}],"specRefs":[{"board":"AQA","code":"8462","section":"4.2.1 Chemical bonds (ionic, covalent)","url":"https://www.aqa.org.uk/subjects/chemistry/gcse/chemistry-8462/specification"}],"route":"gcse","subject":"Chemistry"},"question_keys":["gcse-chem-bonding:bo1","gcse-chem-bonding:bo2"],"version":"1.0"},{"course_id":"gcse-physics","topic_id":"gcse-phys-energy","course_title":"GCSE Physics","title":"Energy stores and transfers","content":{"summary":"Energy stores, conservation of energy, kinetic and gravitational potential energy, and efficiency.","objectives":["Describe energy stores and the ways energy is transferred","Calculate kinetic and gravitational potential energy","Calculate efficiency"],"explanation":["Energy is stored in stores such as kinetic, gravitational potential, elastic potential, thermal, chemical and nuclear. It is transferred by forces doing work, electrical currents, heating and radiation.","Energy cannot be created or destroyed, only transferred between stores. In real systems some energy is dissipated, usually to the thermal store of the surroundings.","Kinetic energy: Eₖ = ½ m v². Gravitational potential energy: Eₚ = m g h, where g is the gravitational field strength (about 9.8 N/kg on Earth; check which value your exam uses).","Efficiency = useful output energy ÷ total input energy. It can be written as a decimal or percentage and can never be more than 1 (100%)."],"workedExample":{"question":"A 2 kg ball moves at 3 m/s. What is its kinetic energy?","steps":["Eₖ = ½ m v².","= 0.5 × 2 × 3².","= 0.5 × 2 × 9 = 9 J."],"answer":"9 J"},"keyTerms":[{"term":"Conservation of energy","definition":"Energy can be transferred, stored or dissipated, but not created or destroyed."},{"term":"Dissipated","definition":"Energy spread out to the surroundings, usually as a less useful thermal store."},{"term":"Efficiency","definition":"Useful output energy ÷ total input energy."},{"term":"Joule (J)","definition":"The unit of energy."}],"misconceptions":[{"wrong":"Energy is used up.","right":"Energy is transferred to other stores, often dissipated to the surroundings."},{"wrong":"Doubling speed doubles kinetic energy.","right":"Eₖ depends on v², so doubling speed quadruples kinetic energy."}],"retrieval":[{"q":"Write the equation for kinetic energy.","a":"Eₖ = ½ m v²"},{"q":"A machine transfers 200 J usefully from 500 J input. Efficiency?","a":"0.4 or 40%"},{"q":"Name four energy stores.","a":"Any four of: kinetic, gravitational potential, elastic potential, thermal, chemical, nuclear, magnetic, electrostatic."}],"specRefs":[{"board":"AQA","code":"8463","section":"4.1.1 Energy stores and systems","url":"https://www.aqa.org.uk/subjects/physics/gcse/physics-8463/specification"}],"route":"gcse","subject":"Physics"},"question_keys":["gcse-phys-energy:eg1","gcse-phys-energy:eg2","gcse-phys-energy:eg3"],"version":"1.0"},{"course_id":"gcse-physics","topic_id":"gcse-phys-forces","course_title":"GCSE Physics","title":"Forces and Newton''s laws","content":{"summary":"Resultant forces, weight, and Newton''s three laws of motion.","objectives":["Calculate resultant force and weight","Apply F = m a","Describe Newton''s first and third laws"],"explanation":["Forces are vectors: they have size and direction. The resultant force is the single force that has the same effect as all the forces acting together.","Newton''s first law: if the resultant force is zero, a stationary object stays still and a moving object keeps moving at the same speed in the same direction.","Newton''s second law: resultant force = mass × acceleration (F = m a). A larger resultant force gives a larger acceleration; a larger mass gives a smaller one.","Weight is the force of gravity on a mass: W = m g. Mass is measured in kilograms, weight in newtons.","Newton''s third law: when two objects interact, they exert equal and opposite forces on each other. The two forces act on different objects."],"workedExample":{"question":"A 1200 kg car accelerates at 2 m/s². What resultant force acts on it?","steps":["F = m a.","F = 1200 × 2 = 2400 N."],"answer":"2400 N"},"keyTerms":[{"term":"Resultant force","definition":"The single force that has the same effect as all the forces acting on an object."},{"term":"Newton (N)","definition":"The unit of force."},{"term":"Weight","definition":"The force acting on an object due to gravity; W = m g."},{"term":"Vector","definition":"A quantity with both magnitude and direction."}],"misconceptions":[{"wrong":"A moving object needs a resultant force to keep moving.","right":"With zero resultant force it keeps moving at constant velocity."},{"wrong":"Third-law force pairs cancel out.","right":"They act on different objects, so they do not cancel."}],"retrieval":[{"q":"What is the unit of force?","a":"The newton (N)."},{"q":"State Newton''s second law as an equation.","a":"F = m a"},{"q":"What is the weight of a 50 kg person if g = 9.8 N/kg?","a":"490 N"}],"specRefs":[{"board":"AQA","code":"8463","section":"4.5 Forces; 4.5.6.2 Newton''s laws","url":"https://www.aqa.org.uk/subjects/physics/gcse/physics-8463/specification"}],"route":"gcse","subject":"Physics"},"question_keys":["gcse-phys-forces:fo1","gcse-phys-forces:fo2","gcse-phys-forces:fo3"],"version":"1.0"}]'::jsonb) on conflict(course_id,topic_id) do update set course_title=excluded.course_title,title=excluded.title,content=excluded.content,question_keys=excluded.question_keys,version=excluded.version;
insert into public.subject_quest_catalogue select * from jsonb_populate_recordset(null::public.subject_quest_catalogue,'[{"course_id":"gcse-combined-science","topic_id":"gcse-bio-cells","course_title":"GCSE Combined Science","title":"Cell structure","content":{"summary":"Compare animal, plant and bacterial cells and the jobs of their parts.","objectives":["Name the main structures in animal and plant cells and state their functions","Compare eukaryotic and prokaryotic cells","Use magnification = image size ÷ actual size"],"explanation":["Animal and plant cells are eukaryotic: their genetic material is enclosed in a nucleus. Both have a nucleus, cytoplasm, cell membrane, mitochondria and ribosomes.","Plant cells also usually have a cellulose cell wall for support, chloroplasts for photosynthesis and a permanent vacuole containing cell sap.","Bacterial cells are prokaryotic. They are much smaller, have no nucleus (their DNA is a single loop in the cytoplasm) and may contain small rings of DNA called plasmids.","Magnification = image size ÷ actual size. Convert units first so both sizes use the same unit (1 mm = 1000 µm)."],"workedExample":{"question":"A cell drawing is 40 mm long. The real cell is 0.08 mm long. What is the magnification?","steps":["Magnification = image ÷ actual.","40 ÷ 0.08 = 500."],"answer":"×500"},"keyTerms":[{"term":"Nucleus","definition":"Contains genetic material and controls the activities of the cell."},{"term":"Mitochondria","definition":"Where most aerobic respiration reactions take place, releasing energy."},{"term":"Ribosome","definition":"Site of protein synthesis."},{"term":"Chloroplast","definition":"Contains chlorophyll; where photosynthesis takes place."},{"term":"Plasmid","definition":"A small ring of DNA found in many bacterial cells."}],"misconceptions":[{"wrong":"Mitochondria make energy.","right":"Energy cannot be made. Respiration in mitochondria releases energy stored in glucose."},{"wrong":"All plant cells have chloroplasts.","right":"Cells not exposed to light, such as root hair cells, do not have chloroplasts."}],"retrieval":[{"q":"Name three structures found in plant cells but not animal cells.","a":"Cell wall, chloroplasts, permanent vacuole."},{"q":"Where is the DNA in a bacterial cell?","a":"A single loop in the cytoplasm, plus plasmids."},{"q":"Write the magnification equation.","a":"Magnification = image size ÷ actual size."}],"specRefs":[{"board":"AQA","code":"8461","section":"4.1.1 Cell structure","url":"https://www.aqa.org.uk/subjects/biology/gcse/biology-8461/specification"}],"route":"gcse","subject":"Combined Science","foundationFrom":"GCSE Biology"},"question_keys":["gcse-bio-cells:ce1","gcse-bio-cells:ce2","gcse-bio-cells:ce3","gcse-bio-cells:ce4"],"version":"1.0"},{"course_id":"gcse-combined-science","topic_id":"gcse-chem-atomic-structure","course_title":"GCSE Combined Science","title":"Atomic structure","content":{"summary":"Protons, neutrons and electrons, atomic and mass numbers, isotopes and electron configuration.","objectives":["Describe the structure of an atom and the relative charge and mass of subatomic particles","Use atomic number and mass number to work out numbers of particles","Explain what isotopes are and write simple electron configurations"],"explanation":["An atom has a tiny central nucleus containing protons and neutrons, surrounded by electrons in shells (energy levels). Most of an atom''s mass is in the nucleus.","Relative charges: proton +1, neutron 0, electron −1. Relative masses: proton 1, neutron 1, electron very small (about 1/2000).","Atomic number = number of protons (and electrons in a neutral atom). Mass number = protons + neutrons, so neutrons = mass number − atomic number.","Isotopes are atoms of the same element with the same number of protons but different numbers of neutrons.","For the first 20 elements, the first shell holds up to 2 electrons and the second and third shells hold up to 8 each, e.g. sodium (11 electrons) is 2,8,1 and calcium (20 electrons) is 2,8,8,2."],"workedExample":{"question":"Chlorine-37 has atomic number 17. How many protons, neutrons and electrons does a chlorine-37 atom have?","steps":["Protons = atomic number = 17.","Electrons = protons in a neutral atom = 17.","Neutrons = 37 − 17 = 20."],"answer":"17 protons, 20 neutrons, 17 electrons"},"keyTerms":[{"term":"Atomic number","definition":"The number of protons in the nucleus of an atom."},{"term":"Mass number","definition":"The total number of protons and neutrons in an atom."},{"term":"Isotope","definition":"Atoms of the same element with different numbers of neutrons."},{"term":"Electron shell","definition":"An energy level that electrons occupy around the nucleus."}],"misconceptions":[{"wrong":"Isotopes have different numbers of protons.","right":"Isotopes have the same number of protons; only the neutron number differs."},{"wrong":"Electrons are in the nucleus.","right":"Electrons occupy shells around the nucleus."}],"retrieval":[{"q":"What is the charge of a neutron?","a":"0 (no charge)."},{"q":"How do you calculate the number of neutrons?","a":"Mass number − atomic number."},{"q":"Write the electron configuration of magnesium (12 electrons).","a":"2,8,2"}],"specRefs":[{"board":"AQA","code":"8462","section":"4.1.1 A simple model of the atom","url":"https://www.aqa.org.uk/subjects/chemistry/gcse/chemistry-8462/specification"}],"route":"gcse","subject":"Combined Science","foundationFrom":"GCSE Chemistry"},"question_keys":["gcse-chem-atomic-structure:at1","gcse-chem-atomic-structure:at2","gcse-chem-atomic-structure:at3"],"version":"1.1"},{"course_id":"gcse-combined-science","topic_id":"gcse-phys-energy","course_title":"GCSE Combined Science","title":"Energy stores and transfers","content":{"summary":"Energy stores, conservation of energy, kinetic and gravitational potential energy, and efficiency.","objectives":["Describe energy stores and the ways energy is transferred","Calculate kinetic and gravitational potential energy","Calculate efficiency"],"explanation":["Energy is stored in stores such as kinetic, gravitational potential, elastic potential, thermal, chemical and nuclear. It is transferred by forces doing work, electrical currents, heating and radiation.","Energy cannot be created or destroyed, only transferred between stores. In real systems some energy is dissipated, usually to the thermal store of the surroundings.","Kinetic energy: Eₖ = ½ m v². Gravitational potential energy: Eₚ = m g h, where g is the gravitational field strength (about 9.8 N/kg on Earth; check which value your exam uses).","Efficiency = useful output energy ÷ total input energy. It can be written as a decimal or percentage and can never be more than 1 (100%)."],"workedExample":{"question":"A 2 kg ball moves at 3 m/s. What is its kinetic energy?","steps":["Eₖ = ½ m v².","= 0.5 × 2 × 3².","= 0.5 × 2 × 9 = 9 J."],"answer":"9 J"},"keyTerms":[{"term":"Conservation of energy","definition":"Energy can be transferred, stored or dissipated, but not created or destroyed."},{"term":"Dissipated","definition":"Energy spread out to the surroundings, usually as a less useful thermal store."},{"term":"Efficiency","definition":"Useful output energy ÷ total input energy."},{"term":"Joule (J)","definition":"The unit of energy."}],"misconceptions":[{"wrong":"Energy is used up.","right":"Energy is transferred to other stores, often dissipated to the surroundings."},{"wrong":"Doubling speed doubles kinetic energy.","right":"Eₖ depends on v², so doubling speed quadruples kinetic energy."}],"retrieval":[{"q":"Write the equation for kinetic energy.","a":"Eₖ = ½ m v²"},{"q":"A machine transfers 200 J usefully from 500 J input. Efficiency?","a":"0.4 or 40%"},{"q":"Name four energy stores.","a":"Any four of: kinetic, gravitational potential, elastic potential, thermal, chemical, nuclear, magnetic, electrostatic."}],"specRefs":[{"board":"AQA","code":"8463","section":"4.1.1 Energy stores and systems","url":"https://www.aqa.org.uk/subjects/physics/gcse/physics-8463/specification"}],"route":"gcse","subject":"Combined Science","foundationFrom":"GCSE Physics"},"question_keys":["gcse-phys-energy:eg1","gcse-phys-energy:eg2","gcse-phys-energy:eg3"],"version":"1.0"},{"course_id":"gcse-history","topic_id":"gcse-history-sources","course_title":"GCSE History","title":"Evaluating historical sources","content":{"summary":"Judge how useful or reliable a source is using its content, provenance and your own knowledge.","objectives":["Use the content of a source as evidence","Evaluate provenance: nature, origin and purpose","Support judgements with contextual own knowledge"],"explanation":["A source''s usefulness depends on the question being asked. A biased poster can be very useful for studying propaganda, even if it is unreliable about events.","Content: what does the source show or say? Pick specific details and link them to the enquiry.","Provenance: who made it, when, why and for whom? Think about NOP: nature, origin, purpose. A private diary and a public speech have very different purposes.","Own knowledge: use accurate contextual knowledge to confirm, challenge or add to what the source shows.","Reach a supported judgement. Avoid simply saying a source is biased and therefore useless."],"workedExample":null,"keyTerms":[{"term":"Provenance","definition":"Where a source comes from: who created it, when and why."},{"term":"Primary source","definition":"A source created at the time being studied."},{"term":"Utility","definition":"How useful a source is for a particular enquiry."},{"term":"Interpretation","definition":"A later view of the past by a historian or other writer."}],"misconceptions":[{"wrong":"Biased sources are useless.","right":"Bias can itself be useful evidence, for example about attitudes or propaganda."},{"wrong":"Primary sources are always more reliable than secondary.","right":"Reliability depends on provenance and purpose, not only on date."}],"retrieval":[{"q":"What does NOP stand for?","a":"Nature, origin, purpose."},{"q":"Can a biased source be useful? Why?","a":"Yes. It can show opinions, attitudes or propaganda methods."},{"q":"What three things should a utility answer use?","a":"Content, provenance and own knowledge."}],"specRefs":[{"board":"AQA","code":"8145","section":"AO3 source analysis","url":"https://www.aqa.org.uk/subjects/history/gcse/history-8145/specification"}],"route":"gcse","subject":"History"},"question_keys":["gcse-history-sources:hs1","gcse-history-sources:hs2"],"version":"1.0"},{"course_id":"gcse-geography","topic_id":"gcse-geog-tectonics","course_title":"GCSE Geography","title":"Tectonic hazards","content":{"summary":"Plate boundaries, earthquakes, volcanoes and how people reduce the risk.","objectives":["Describe the global distribution of earthquakes and volcanoes","Explain processes at constructive, destructive and conservative plate margins","Evaluate monitoring, prediction, protection and planning"],"explanation":["The Earth''s crust is broken into tectonic plates that move slowly, driven by processes in the mantle. Most earthquakes and volcanoes occur along plate margins.","At constructive (divergent) margins, plates move apart and magma rises, forming new crust and relatively gentle eruptions.","At destructive (convergent) margins, a denser oceanic plate subducts beneath another plate. Friction and pressure build, causing powerful earthquakes, and melting creates explosive volcanoes.","At conservative margins, plates slide past each other. Pressure builds and is released as earthquakes, but there are no volcanoes.","People reduce risk through monitoring, prediction, protection (e.g. earthquake-resistant buildings) and planning (e.g. evacuation routes and drills). Effects are usually greater where countries have fewer resources to prepare and respond."],"workedExample":null,"keyTerms":[{"term":"Plate margin","definition":"The boundary where two tectonic plates meet."},{"term":"Subduction","definition":"When a denser oceanic plate sinks beneath another plate."},{"term":"Primary effects","definition":"The immediate effects of a hazard, e.g. buildings collapsing."},{"term":"Secondary effects","definition":"Effects that result from primary effects, e.g. fires or disease."}],"misconceptions":[{"wrong":"Earthquakes can be accurately predicted.","right":"Earthquakes cannot yet be precisely predicted; monitoring helps assess risk. Volcanic eruptions are easier to forecast."},{"wrong":"All plate margins have volcanoes.","right":"Conservative margins produce earthquakes but no volcanoes."}],"retrieval":[{"q":"What happens at a destructive margin?","a":"A denser oceanic plate subducts under another plate, causing earthquakes and explosive volcanoes."},{"q":"Name the four ways of managing (reducing the risk of) tectonic hazards.","a":"Monitoring, prediction, protection, planning."},{"q":"Give a secondary effect of an earthquake.","a":"E.g. fires, tsunamis, disease, homelessness, economic loss."}],"specRefs":[{"board":"AQA","code":"8035","section":"3.1.1.2 Tectonic hazards","url":"https://www.aqa.org.uk/subjects/geography/gcse/geography-8035/specification"}],"route":"gcse","subject":"Geography"},"question_keys":["gcse-geog-tectonics:tc1","gcse-geog-tectonics:tc2"],"version":"1.1"},{"course_id":"gcse-computer-science","topic_id":"gcse-cs-binary","course_title":"GCSE Computer Science","title":"Binary and data representation","content":{"summary":"Convert between denary, binary and hexadecimal and understand units of data.","objectives":["Convert between denary and 8-bit binary","Convert between binary and hexadecimal","Use units of data from bits to terabytes"],"explanation":["Computers use binary (base 2) because their circuits have two states: on and off. Each binary digit is a bit.","In an 8-bit number the place values are 128, 64, 32, 16, 8, 4, 2, 1. For example, 01001101 = 64 + 8 + 4 + 1 = 77.","Hexadecimal (base 16) uses 0–9 and A–F (A = 10 … F = 15). Each hex digit represents exactly 4 bits (a nibble), so 1111 0101 = F5.","Units: 8 bits = 1 byte and 4 bits = 1 nibble. OCR uses 1 kilobyte (KB) = 1000 bytes but also accepts 1024. AQA uses 1 kB = 1000 bytes and 1 kibibyte (KiB) = 1024 bytes. Pearson Edexcel uses binary multiples, e.g. 1 kibibyte (KiB) = 1024 bytes. Check which your board expects."],"workedExample":{"question":"Convert 1011 0110 to denary and hexadecimal.","steps":["Place values: 128 + 32 + 16 + 4 + 2 = 182.","Split into nibbles: 1011 = 11 = B, 0110 = 6.","Hex = B6."],"answer":"182 in denary, B6 in hexadecimal"},"keyTerms":[{"term":"Bit","definition":"A single binary digit, 0 or 1."},{"term":"Byte","definition":"A group of 8 bits."},{"term":"Nibble","definition":"4 bits; one hexadecimal digit."},{"term":"Hexadecimal","definition":"Base 16 number system using 0–9 and A–F."}],"misconceptions":[{"wrong":"Hexadecimal is used because computers process it directly.","right":"Computers still process binary; hex is a shorter, more readable way for humans to write it."},{"wrong":"The largest 8-bit number is 256.","right":"It is 255 (11111111); there are 256 values from 0 to 255."}],"retrieval":[{"q":"Convert 00101010 to denary.","a":"42"},{"q":"What is the largest number an 8-bit binary number can hold?","a":"255"},{"q":"Convert hex 3C to binary.","a":"0011 1100"}],"specRefs":[{"board":"AQA","code":"8525","section":"3.3 Fundamentals of data representation","url":"https://www.aqa.org.uk/subjects/computer-science-and-it/gcse/computer-science-8525/specification"},{"board":"OCR","code":"J277","section":"1.2 Memory and storage"},{"board":"Pearson","code":"1CP2","section":"Topic 2 Data"}],"route":"gcse","subject":"Computer Science"},"question_keys":["gcse-cs-binary:bi1","gcse-cs-binary:bi2","gcse-cs-binary:bi3"],"version":"1.1"},{"course_id":"alevel-maths","topic_id":"alevel-maths-differentiation","course_title":"A level Mathematics","title":"Differentiation from first principles to tangents","content":{"summary":"Gradients of curves, the power rule, and finding tangents and stationary points.","objectives":["Interpret the derivative as the gradient of a curve","Differentiate sums of powers of x using the power rule","Find equations of tangents and locate stationary points"],"explanation":["The derivative dy/dx gives the gradient of a curve at any point. From first principles, f′(x) is the limit of [f(x + h) − f(x)] ÷ h as h → 0.","Power rule: if y = xⁿ, then dy/dx = n xⁿ⁻¹. Differentiate term by term; constants differentiate to 0.","Rewrite roots and fractions as powers first: √x = x^½ and 1/x² = x⁻².","A tangent at x = a has gradient f′(a) and passes through (a, f(a)). Use y − y₁ = m(x − x₁).","Stationary points occur where dy/dx = 0. Use the second derivative: if d²y/dx² > 0 it is a minimum, if < 0 a maximum. If d²y/dx² = 0 the test is inconclusive; check the gradient either side."],"workedExample":{"question":"Find the stationary points of y = x³ − 3x and their nature.","steps":["dy/dx = 3x² − 3.","Set 3x² − 3 = 0, so x² = 1 and x = ±1.","x = 1: y = −2; x = −1: y = 2.","d²y/dx² = 6x. At x = 1 it is 6 > 0 (minimum); at x = −1 it is −6 < 0 (maximum)."],"answer":"Minimum at (1, −2); maximum at (−1, 2)"},"keyTerms":[{"term":"Derivative","definition":"The rate of change of a function; the gradient function."},{"term":"Stationary point","definition":"A point where the gradient is zero."},{"term":"Tangent","definition":"A straight line touching a curve at a point with the same gradient."},{"term":"Normal","definition":"A line perpendicular to the tangent at a point; gradient −1/m."}],"misconceptions":[{"wrong":"The derivative of 1/x is 1.","right":"Write it as x⁻¹; the derivative is −x⁻² = −1/x²."},{"wrong":"A stationary point is always a maximum or minimum.","right":"It can also be a point of inflection; check with the second derivative or gradient either side."}],"retrieval":[{"q":"Differentiate y = 4x³.","a":"12x²"},{"q":"What condition defines a stationary point?","a":"dy/dx = 0"},{"q":"Differentiate y = √x.","a":"½x^(−½) = 1/(2√x)"}],"specRefs":[{"board":"AQA","code":"7357","section":"G1–G3 Differentiation","url":"https://www.aqa.org.uk/subjects/mathematics/a-level/mathematics-7357/specification"}],"route":"alevel","subject":"Mathematics"},"question_keys":["alevel-maths-differentiation:df1","alevel-maths-differentiation:df2","alevel-maths-differentiation:df3"],"version":"1.1"},{"course_id":"alevel-further-maths","topic_id":"alevel-fmaths-complex-numbers","course_title":"A level Further Mathematics","title":"Complex numbers and the Argand diagram","content":{"summary":"Arithmetic with complex numbers, conjugates, Argand diagrams and modulus–argument form.","objectives":["Add, subtract, multiply and divide complex numbers in the form x + iy","Use complex conjugates, including conjugate pairs of roots","Represent complex numbers on an Argand diagram","Convert between Cartesian and modulus–argument form"],"explanation":["A complex number has the form z = x + iy, where i² = −1, x = Re(z) is the real part and y = Im(z) is the imaginary part. Add and subtract by collecting real and imaginary parts; multiply by expanding brackets and replacing i² with −1.","The complex conjugate of z = x + iy is z* = x − iy. The product zz* = x² + y² is always real, so to divide, multiply the numerator and denominator by the conjugate of the denominator.","If a polynomial equation has real coefficients, its non-real roots occur in conjugate pairs. So if 2 + 3i is a root of a real cubic, 2 − 3i is also a root, and the product (z − (2 + 3i))(z − (2 − 3i)) = z² − 4z + 13 is a real quadratic factor.","On an Argand diagram, z = x + iy is plotted as the point (x, y). The modulus |z| = √(x² + y²) is its distance from the origin. The argument arg z is the angle from the positive real axis, measured anticlockwise; the principal argument lies in −π < θ ≤ π.","In modulus–argument form, z = r(cos θ + i sin θ). When multiplying, multiply the moduli and add the arguments; when dividing, divide the moduli and subtract the arguments. Always sketch the point first so you place the argument in the correct quadrant."],"workedExample":{"question":"Given z₁ = 3 + 4i and z₂ = 1 − 2i, find z₁z₂ and z₁ ÷ z₂ in the form x + iy, and find |z₁|.","steps":["z₁z₂ = (3 + 4i)(1 − 2i) = 3 − 6i + 4i − 8i².","Replace i² with −1: 3 − 2i + 8 = 11 − 2i.","For the division, multiply top and bottom by z₂* = 1 + 2i: (3 + 4i)(1 + 2i) ÷ (1 + 2i)(1 − 2i).","Numerator: 3 + 6i + 4i + 8i² = −5 + 10i. Denominator: 1² + 2² = 5.","So z₁ ÷ z₂ = (−5 + 10i) ÷ 5 = −1 + 2i.","|z₁| = √(3² + 4²) = √25 = 5."],"answer":"z₁z₂ = 11 − 2i, z₁ ÷ z₂ = −1 + 2i and |z₁| = 5"},"keyTerms":[{"term":"Complex conjugate","definition":"For z = x + iy, the conjugate is z* = x − iy."},{"term":"Argand diagram","definition":"A diagram with a real axis and an imaginary axis on which complex numbers are plotted as points."},{"term":"Modulus","definition":"The distance of z from the origin on an Argand diagram: |z| = √(x² + y²)."},{"term":"Argument","definition":"The angle z makes with the positive real axis; the principal argument lies in −π < θ ≤ π."}],"misconceptions":[{"wrong":"arg z is always arctan(y/x).","right":"arctan(y/x) only gives the right angle in the first and fourth quadrants. Sketch the point and adjust by π when x is negative."},{"wrong":"To divide complex numbers, divide the real parts and the imaginary parts separately.","right":"Multiply the numerator and denominator by the conjugate of the denominator, so the denominator becomes real."}],"retrieval":[{"q":"What is the conjugate of 4 − 7i?","a":"4 + 7i."},{"q":"If 1 − i is a root of a polynomial with real coefficients, name another root.","a":"1 + i."},{"q":"How do you multiply two complex numbers in modulus–argument form?","a":"Multiply the moduli and add the arguments."}],"specRefs":[{"board":"AQA","code":"7367","section":"B2–B6 Complex numbers","url":"https://www.aqa.org.uk/subjects/mathematics/a-level/further-mathematics-7367/specification/subject-content/compulsory-content"}],"route":"alevel","subject":"Further Mathematics"},"question_keys":["alevel-fmaths-complex-numbers:cx1","alevel-fmaths-complex-numbers:cx2","alevel-fmaths-complex-numbers:cx3"],"version":"1.0"},{"course_id":"alevel-biology","topic_id":"alevel-bio-cell-division","course_title":"A level Biology","title":"Mitosis and the cell cycle","content":{"summary":"The stages of the cell cycle and mitosis, and why mitosis matters.","objectives":["Describe the stages of the cell cycle","Describe prophase, metaphase, anaphase and telophase","Calculate a mitotic index"],"explanation":["The cell cycle has interphase (growth and DNA replication), mitosis (nuclear division) and cytokinesis (division of the cytoplasm).","Prophase: chromosomes condense and become visible, the nuclear envelope breaks down and spindle fibres form.","Metaphase: chromosomes line up along the equator of the cell, attached to spindle fibres by their centromeres.","Anaphase: centromeres divide and sister chromatids are pulled to opposite poles.","Telophase: chromosomes reach the poles and uncoil, and nuclear envelopes reform. Mitosis produces two genetically identical daughter cells, used for growth, repair and asexual reproduction.","Mitotic index = number of cells in mitosis ÷ total number of cells observed."],"workedExample":null,"keyTerms":[{"term":"Interphase","definition":"The stage where the cell grows and DNA replicates."},{"term":"Sister chromatids","definition":"Two identical copies of a DNA molecule (chromatids), made by replication and joined at a centromere to form one chromosome."},{"term":"Spindle fibres","definition":"Protein fibres that separate chromatids during mitosis."},{"term":"Mitotic index","definition":"The proportion of cells undergoing mitosis."}],"misconceptions":[{"wrong":"DNA replicates during mitosis.","right":"DNA replicates during interphase (S phase), before mitosis starts."},{"wrong":"Mitosis produces genetically varied cells.","right":"Mitosis produces genetically identical cells; meiosis introduces variation."}],"retrieval":[{"q":"In which stage do chromosomes line up at the equator?","a":"Metaphase."},{"q":"When does DNA replication happen?","a":"Interphase (S phase)."},{"q":"20 of 400 cells are in mitosis. Mitotic index?","a":"0.05 (5%)"}],"specRefs":[{"board":"AQA","code":"7402","section":"3.2.2 All cells arise from other cells","url":"https://www.aqa.org.uk/subjects/biology/a-level/biology-7402/specification"}],"route":"alevel","subject":"Biology"},"question_keys":["alevel-bio-cell-division:cd1","alevel-bio-cell-division:cd2"],"version":"1.1"},{"course_id":"alevel-chemistry","topic_id":"alevel-chem-equilibria","course_title":"A level Chemistry","title":"Chemical equilibria","content":{"summary":"Dynamic equilibrium, Le Chatelier''s principle and the equilibrium constant Kc.","objectives":["Describe dynamic equilibrium","Use Le Chatelier''s principle to predict shifts in equilibrium position","Write and calculate Kc for homogeneous equilibria"],"explanation":["In a closed system, a reversible reaction reaches dynamic equilibrium when the forward and reverse rates are equal and concentrations stay constant.","Le Chatelier''s principle: if a change is made to a system at equilibrium, the position shifts to oppose the change.","Increasing pressure shifts equilibrium towards the side with fewer gas molecules. Increasing temperature shifts it in the endothermic direction.","A catalyst increases the rates of the forward and reverse reactions equally. It helps equilibrium be reached faster but does not change the position.","For aA + bB ⇌ cC + dD, Kc = [C]ᶜ[D]ᵈ ÷ [A]ᵃ[B]ᵇ. Only temperature changes the value of Kc."],"workedExample":null,"keyTerms":[{"term":"Dynamic equilibrium","definition":"Forward and reverse reactions happen at equal rates, so concentrations stay constant."},{"term":"Le Chatelier''s principle","definition":"A system at equilibrium shifts to oppose a change."},{"term":"Kc","definition":"The equilibrium constant in terms of concentrations."},{"term":"Closed system","definition":"No substances enter or leave."}],"misconceptions":[{"wrong":"At equilibrium the reactions stop.","right":"Both reactions continue at equal rates. It is dynamic."},{"wrong":"Changing concentration changes Kc.","right":"The position shifts but Kc stays the same; only temperature changes Kc."}],"retrieval":[{"q":"What does a catalyst do to the position of equilibrium?","a":"Nothing. It only helps equilibrium be reached faster."},{"q":"What is the only factor that changes Kc?","a":"Temperature."},{"q":"Increasing pressure shifts equilibrium towards…?","a":"The side with fewer gas molecules."}],"specRefs":[{"board":"AQA","code":"7405","section":"3.1.6 Chemical equilibria; 3.1.10 Kp","url":"https://www.aqa.org.uk/subjects/chemistry/a-level/chemistry-7405/specification"}],"route":"alevel","subject":"Chemistry"},"question_keys":["alevel-chem-equilibria:eq1","alevel-chem-equilibria:eq2","alevel-chem-equilibria:eq3"],"version":"1.0"}]'::jsonb) on conflict(course_id,topic_id) do update set course_title=excluded.course_title,title=excluded.title,content=excluded.content,question_keys=excluded.question_keys,version=excluded.version;
insert into public.subject_quest_catalogue select * from jsonb_populate_recordset(null::public.subject_quest_catalogue,'[{"course_id":"alevel-physics","topic_id":"alevel-physics-suvat","course_title":"A level Physics","title":"Motion in a straight line and the SUVAT equations","content":{"summary":"Displacement, velocity and acceleration, motion graphs, and the equations for uniformly accelerated motion.","objectives":["Distinguish between scalar and vector quantities in kinematics","Interpret gradients and areas of displacement–time and velocity–time graphs","Select and apply the SUVAT equations to problems with constant acceleration","Apply the equations to free fall using g = 9.81 m s⁻²"],"explanation":["Displacement (s) is distance in a stated direction, so it is a vector; distance is a scalar. In the same way, velocity is speed in a stated direction. Choose a positive direction at the start of every problem and give every vector a sign.","Velocity is the rate of change of displacement, v = Δs/Δt, and acceleration is the rate of change of velocity, a = Δv/Δt. The gradient of a displacement–time graph gives velocity, the gradient of a velocity–time graph gives acceleration, and the area under a velocity–time graph gives displacement.","For constant (uniform) acceleration only, the five quantities s, u, v, a and t are linked by four equations: v = u + at, s = ½(u + v)t, s = ut + ½at² and v² = u² + 2as. Each equation leaves out one quantity, so list the three you know and the one you want, then pick the equation that leaves out the fifth.","Near the Earth''s surface, and ignoring air resistance, every object in free fall has the same downward acceleration, g = 9.81 m s⁻². If you take upwards as positive, a = −9.81 m s⁻² for the whole flight, including the instant at the top when v = 0.","Required practical 3 measures g by timing free fall over measured heights. Plotting s against t² for an object released from rest gives a straight line through the origin with gradient ½g, which reduces the effect of random error compared with a single measurement."],"workedExample":{"question":"A car accelerates uniformly from 4.0 m s⁻¹ to 16.0 m s⁻¹ over a distance of 60 m. Find its acceleration and the time taken.","steps":["Known: u = 4.0 m s⁻¹, v = 16.0 m s⁻¹, s = 60 m. Unknown: a, then t.","Time is not given, so use v² = u² + 2as: 16.0² = 4.0² + 2 × a × 60.","256 = 16 + 120a, so 120a = 240 and a = 2.0 m s⁻².","Now use v = u + at: 16.0 = 4.0 + 2.0t, so t = 6.0 s.","Check with s = ½(u + v)t = ½ × 20.0 × 6.0 = 60 m. ✓"],"answer":"a = 2.0 m s⁻² and t = 6.0 s"},"keyTerms":[{"term":"Displacement","definition":"The distance moved in a stated direction from a reference point; a vector."},{"term":"Velocity","definition":"The rate of change of displacement; a vector."},{"term":"Acceleration","definition":"The rate of change of velocity, measured in m s⁻²; a vector."},{"term":"Uniform acceleration","definition":"Acceleration that stays constant in size and direction; the condition for using SUVAT."}],"misconceptions":[{"wrong":"At the top of its flight, a ball thrown upwards has zero acceleration.","right":"Its velocity is zero for an instant, but its acceleration is still g downwards throughout."},{"wrong":"The SUVAT equations work for any motion.","right":"They only apply when acceleration is constant. For changing acceleration, use graphs (gradients and areas) instead."},{"wrong":"Speed and velocity are the same thing.","right":"Velocity has a direction, so its sign matters. An object can have constant speed but changing velocity."}],"retrieval":[{"q":"What does the area under a velocity–time graph represent?","a":"Displacement."},{"q":"Which SUVAT equation does not contain time?","a":"v² = u² + 2as."},{"q":"An object is released from rest. What is its velocity after 3.0 s of free fall?","a":"v = u + at = 0 + 9.81 × 3.0 = 29.4 m s⁻¹ (downwards)."}],"specRefs":[{"board":"AQA","code":"7408","section":"3.4.1.3 Motion along a straight line","url":"https://www.aqa.org.uk/subjects/physics/a-level/physics-7408/specification/subject-content/mechanics-and-materials"}],"route":"alevel","subject":"Physics"},"question_keys":["alevel-physics-suvat:sv1","alevel-physics-suvat:sv2","alevel-physics-suvat:sv3"],"version":"1.0"},{"course_id":"alevel-psychology","topic_id":"alevel-psych-research-methods","course_title":"A level Psychology","title":"Research methods: experiments and variables","content":{"summary":"Independent and dependent variables, hypotheses, experimental designs and controls.","objectives":["Identify and operationalise IV and DV","Write directional and non-directional hypotheses","Compare independent groups, repeated measures and matched pairs designs"],"explanation":["The independent variable (IV) is manipulated by the researcher; the dependent variable (DV) is measured. Operationalising means defining variables so they can be measured precisely.","A directional hypothesis predicts the direction of a difference; a non-directional one predicts a difference without saying which way.","Independent groups: different participants in each condition (no order effects, but participant variables). Repeated measures: the same participants do all conditions (controls participant variables, but order effects, so use counterbalancing). Matched pairs: participants matched on key variables (reduces participant variables, but time-consuming).","Extraneous variables could affect the DV; if they vary systematically with the IV they become confounding variables."],"workedExample":null,"keyTerms":[{"term":"Independent variable","definition":"The variable the researcher manipulates."},{"term":"Dependent variable","definition":"The variable that is measured."},{"term":"Counterbalancing","definition":"Varying the order of conditions to reduce order effects, e.g. ABBA."},{"term":"Confounding variable","definition":"A variable other than the IV that systematically affects the DV."}],"misconceptions":[{"wrong":"Repeated measures has participant variables as its main problem.","right":"Repeated measures controls participant variables; its main problem is order effects."},{"wrong":"Operationalised just means ''defined''.","right":"It means defined in a precise, measurable way (e.g. ''number of words recalled out of 20'')."}],"retrieval":[{"q":"Which design uses the same participants in each condition?","a":"Repeated measures."},{"q":"How can order effects be reduced?","a":"Counterbalancing."},{"q":"What is a directional hypothesis?","a":"One that predicts the direction of the difference or relationship."}],"specRefs":[{"board":"AQA","code":"7182","section":"3.2.3 Research methods","url":"https://www.aqa.org.uk/subjects/psychology/a-level/psychology-7182/specification"}],"route":"alevel","subject":"Psychology"},"question_keys":["alevel-psych-research-methods:rm1","alevel-psych-research-methods:rm2"],"version":"1.0"},{"course_id":"alevel-english-literature","topic_id":"alevel-englit-unseen-poetry","course_title":"A level English Literature","title":"Comparing unseen poems","content":{"summary":"How to read, plan and write a comparative essay on two poems you have not seen before.","objectives":["Use a reliable reading routine for an unseen poem","Build a comparative argument rather than two separate commentaries","Analyse how form, structure and language shape meaning","Meet the assessment objectives, especially AO2 and AO4"],"explanation":["In AQA English Literature A (7712), Paper 1 Section B is a compulsory essay on two unseen poems, worth 25 marks. Other boards also set unseen poetry or prose, so the skills here transfer.","Read each poem at least twice. First get the literal situation: who is speaking, to whom, and what happens. Then look for a turn or shift in tone, often marked by a stanza break, a volta, a change of tense or a short line.","Compare from the start. Write a thesis that links both poems, for example ''Both poets present love as memory, but one treats memory as comfort and the other as loss.'' Then organise paragraphs by idea, not by poem, and move between the two poems within each paragraph using connectives such as ''whereas'' and ''similarly''.","Analyse method, not just meaning. Consider form (sonnet, free verse, dramatic monologue), structure (enjambment, caesura, stanza length, where the poem ends) and language (imagery, sound, verb choices). Always explain the effect: how does the choice shape the reader''s response?","The A level assessment objectives are AO1 (informed, personal and creative responses in accurate, coherent writing), AO2 (analysing how meanings are shaped), AO3 (the significance of contexts), AO4 (connections across texts) and AO5 (different interpretations). In an unseen comparison, the connections you draw between the poems are central."],"workedExample":{"question":"Plan a response to: ''Compare how the poets present the end of a relationship in these two poems.''","steps":["Annotate each poem for situation, speaker, tone and the turning point (about 10 minutes).","Find a shared concern and a key difference, then write a one-sentence comparative thesis.","Choose three ideas to structure the essay, such as memory, blame and acceptance, and pair evidence from both poems under each idea.","For each piece of evidence, name the method (for example enjambment or a shift to present tense) and explain its effect.","Finish with a judgement on which poem reaches resolution and how its ending creates that effect."],"answer":"An idea-led plan that compares both poems in every paragraph, analyses methods and ends with a clear judgement"},"keyTerms":[{"term":"Enjambment","definition":"When a sentence or phrase runs on from one line of poetry into the next without a pause."},{"term":"Caesura","definition":"A pause within a line of poetry, often marked by punctuation."},{"term":"Volta","definition":"A turn in thought or tone within a poem, traditionally found in sonnets."},{"term":"Comparative thesis","definition":"A central argument that links two texts, stating a similarity and a difference."}],"misconceptions":[{"wrong":"Write about the first poem and then the second.","right":"Integrate the comparison throughout. Separate commentaries make it hard to show connections (AO4)."},{"wrong":"Spotting as many techniques as possible gets the marks.","right":"Naming a technique earns little on its own. Explain how it shapes meaning and link it to your argument."},{"wrong":"An unseen poem has one correct meaning you must find.","right":"Examiners reward well-supported, tentative interpretations. Phrases such as ''this could suggest'' are appropriate."}],"retrieval":[{"q":"Which assessment objective is about making connections across texts?","a":"AO4."},{"q":"How should you organise paragraphs in a comparative essay?","a":"By idea or theme, discussing both poems within each paragraph."},{"q":"What is a volta?","a":"A turn in thought or tone within a poem."}],"specRefs":[{"board":"AQA","code":"7712 (A)","section":"3.1 Love through the ages (Paper 1 Section B unseen poetry)","url":"https://www.aqa.org.uk/subjects/english/a-level/english-7712/specification/subject-content/love-through-the-ages"}],"route":"alevel","subject":"English Literature"},"question_keys":["alevel-englit-unseen-poetry:up1","alevel-englit-unseen-poetry:up2","alevel-englit-unseen-poetry:up3"],"version":"1.0"},{"course_id":"alevel-history","topic_id":"alevel-history-interpretations","course_title":"A level History","title":"Evaluating historical interpretations","content":{"summary":"How to analyse and judge historians'' interpretations in extract questions (AO3).","objectives":["Explain the difference between a source and an interpretation","Identify the overall argument of an extract","Evaluate an interpretation using your own contextual knowledge","Reach a supported judgement on how convincing an interpretation is"],"explanation":["AO3 asks you to ''analyse and evaluate, in relation to the historical context, different ways in which aspects of the past have been interpreted''. In AQA 7042, Component 1 Section A gives three extracts from historians and asks how convincing their arguments are (30 marks).","An interpretation is a historian''s argument about the past, written later with hindsight. A source (AO2) is material from the period itself. Do not evaluate an extract as if it were a primary source: comments about the historian''s nationality or the date of publication are rarely useful.","Start by identifying each extract''s overall argument in one sentence. Then pick out its supporting claims, looking for the tone and the key words that show how strongly the historian holds a view.","Evaluate by testing the argument against what you know about the period. Use precise contextual knowledge to corroborate claims (what supports them) and to challenge them (what they leave out or overstate).","Finish each extract with a judgement on how convincing it is overall, and why. Interpretations differ because historians ask different questions, emphasise different evidence or focus on different groups, so explain the reason for a difference rather than just noting it."],"workedExample":{"question":"How should you structure your analysis of one extract in a three-extract AO3 question?","steps":["State the overall argument of the extract in your own words.","Take the first major claim and corroborate it with specific contextual knowledge (dates, events, figures).","Challenge a claim that is overstated or incomplete, again with specific knowledge.","Note what the extract emphasises or leaves out, and why that affects its argument.","Give a clear judgement: how convincing is this interpretation overall?"],"answer":"Argument → corroborate → challenge → emphasis and omission → judgement, repeated for each extract"},"keyTerms":[{"term":"Interpretation","definition":"A historian''s argued view of the past, constructed after the event."},{"term":"Historiography","definition":"The study of how history has been written and how interpretations have changed."},{"term":"Contextual knowledge","definition":"Your own accurate knowledge of the period, used to test an interpretation."},{"term":"Corroborate","definition":"To support a claim with further evidence."}],"misconceptions":[{"wrong":"Evaluate an extract by asking whether the historian was biased.","right":"Assess the argument itself: test its claims against your contextual knowledge."},{"wrong":"Summarising what each extract says is enough.","right":"Summary shows comprehension only. Higher marks need evaluation and a judgement on how convincing each argument is."},{"wrong":"One interpretation must be right and the others wrong.","right":"Interpretations can each be partly convincing. Explain their strengths and limits."}],"retrieval":[{"q":"Which assessment objective covers historical interpretations?","a":"AO3."},{"q":"What is the difference between a source and an interpretation?","a":"A source comes from the period; an interpretation is a historian''s later argument about it."},{"q":"What should you use to test an interpretation''s claims?","a":"Your own precise contextual knowledge."}],"specRefs":[{"board":"AQA","code":"7042","section":"AO3 Interpretations (Component 1 Section A)","url":"https://www.aqa.org.uk/subjects/history/a-level/history-7042/specification/scheme-of-assessment"}],"route":"alevel","subject":"History"},"question_keys":["alevel-history-interpretations:hi1","alevel-history-interpretations:hi2","alevel-history-interpretations:hi3"],"version":"1.0"},{"course_id":"alevel-economics","topic_id":"alevel-econ-supply-demand","course_title":"A level Economics","title":"Supply, demand and market equilibrium","content":{"summary":"What shifts demand and supply curves and how price and quantity respond.","objectives":["Distinguish movements along from shifts of demand and supply curves","Analyse changes in equilibrium price and quantity","Explain price elasticity of demand"],"explanation":["A change in the good''s own price causes a movement along the demand or supply curve. Changes in other factors shift the curve.","Demand shifts with income, prices of substitutes and complements, tastes, advertising and population.","Supply shifts with costs of production, technology, indirect taxes, subsidies and the number of firms.","Equilibrium is where demand equals supply. If demand rises, equilibrium price and quantity both rise. If supply rises, price falls and quantity rises.","Price elasticity of demand (PED) = % change in quantity demanded ÷ % change in price. If |PED| > 1, demand is price elastic."],"workedExample":null,"keyTerms":[{"term":"Equilibrium","definition":"Where quantity demanded equals quantity supplied."},{"term":"Substitute","definition":"A good that can be used in place of another."},{"term":"Complement","definition":"A good used together with another."},{"term":"PED","definition":"The responsiveness of quantity demanded to a change in price."}],"misconceptions":[{"wrong":"A rise in price shifts the demand curve left.","right":"A change in the good''s own price causes a movement along the curve, not a shift."},{"wrong":"Elastic demand means demand changes a lot whatever happens.","right":"PED specifically measures responsiveness to price changes."}],"retrieval":[{"q":"What happens to equilibrium price if supply increases?","a":"It falls (and quantity rises)."},{"q":"Price rises 10% and quantity demanded falls 20%. PED?","a":"−2 (price elastic)"},{"q":"Give two factors that shift supply.","a":"E.g. costs, technology, taxes, subsidies, number of firms."}],"specRefs":[{"board":"AQA","code":"7136","section":"3.1.3 Price determination in a competitive market","url":"https://www.aqa.org.uk/subjects/economics/a-level/economics-7136/specification"}],"route":"alevel","subject":"Economics"},"question_keys":["alevel-econ-supply-demand:sd1","alevel-econ-supply-demand:sd2"],"version":"1.0"},{"course_id":"alevel-computer-science","topic_id":"gcse-cs-binary","course_title":"A level Computer Science","title":"Binary and data representation","content":{"summary":"Convert between denary, binary and hexadecimal and understand units of data.","objectives":["Convert between denary and 8-bit binary","Convert between binary and hexadecimal","Use units of data from bits to terabytes"],"explanation":["Computers use binary (base 2) because their circuits have two states: on and off. Each binary digit is a bit.","In an 8-bit number the place values are 128, 64, 32, 16, 8, 4, 2, 1. For example, 01001101 = 64 + 8 + 4 + 1 = 77.","Hexadecimal (base 16) uses 0–9 and A–F (A = 10 … F = 15). Each hex digit represents exactly 4 bits (a nibble), so 1111 0101 = F5.","Units: 8 bits = 1 byte and 4 bits = 1 nibble. OCR uses 1 kilobyte (KB) = 1000 bytes but also accepts 1024. AQA uses 1 kB = 1000 bytes and 1 kibibyte (KiB) = 1024 bytes. Pearson Edexcel uses binary multiples, e.g. 1 kibibyte (KiB) = 1024 bytes. Check which your board expects."],"workedExample":{"question":"Convert 1011 0110 to denary and hexadecimal.","steps":["Place values: 128 + 32 + 16 + 4 + 2 = 182.","Split into nibbles: 1011 = 11 = B, 0110 = 6.","Hex = B6."],"answer":"182 in denary, B6 in hexadecimal"},"keyTerms":[{"term":"Bit","definition":"A single binary digit, 0 or 1."},{"term":"Byte","definition":"A group of 8 bits."},{"term":"Nibble","definition":"4 bits; one hexadecimal digit."},{"term":"Hexadecimal","definition":"Base 16 number system using 0–9 and A–F."}],"misconceptions":[{"wrong":"Hexadecimal is used because computers process it directly.","right":"Computers still process binary; hex is a shorter, more readable way for humans to write it."},{"wrong":"The largest 8-bit number is 256.","right":"It is 255 (11111111); there are 256 values from 0 to 255."}],"retrieval":[{"q":"Convert 00101010 to denary.","a":"42"},{"q":"What is the largest number an 8-bit binary number can hold?","a":"255"},{"q":"Convert hex 3C to binary.","a":"0011 1100"}],"specRefs":[{"board":"AQA","code":"8525","section":"3.3 Fundamentals of data representation","url":"https://www.aqa.org.uk/subjects/computer-science-and-it/gcse/computer-science-8525/specification"},{"board":"OCR","code":"J277","section":"1.2 Memory and storage"},{"board":"Pearson","code":"1CP2","section":"Topic 2 Data"}],"route":"alevel","subject":"Computer Science","foundationFrom":"GCSE Computer Science"},"question_keys":["gcse-cs-binary:bi1","gcse-cs-binary:bi2","gcse-cs-binary:bi3"],"version":"1.1"},{"course_id":"btec-applied-science","topic_id":"btec-appsci-cells-microscopy","course_title":"BTEC Applied Science","title":"Cell structure, microscopy and magnification","content":{"summary":"Eukaryotic and prokaryotic cells, their organelles, and calculating magnification.","objectives":["Describe the functions of key organelles in animal and plant cells","Compare prokaryotic and eukaryotic cells","Compare light and electron microscopes","Calculate magnification, image size and actual size, converting units"],"explanation":["Eukaryotic cells (animal, plant and fungal) have a nucleus and membrane-bound organelles. The nucleus holds DNA, mitochondria carry out aerobic respiration, ribosomes make proteins, rough endoplasmic reticulum transports proteins made on its ribosomes, and the Golgi apparatus modifies and packages them.","Plant cells also have a cellulose cell wall, a permanent vacuole containing cell sap, and chloroplasts for photosynthesis. Animal cells have none of these.","Prokaryotic cells, such as bacteria, have no nucleus. Their DNA is a single loop in the cytoplasm, often with extra small loops called plasmids. They have smaller (70S) ribosomes than eukaryotic cells (80S), and a cell wall that is not made of cellulose.","Light microscopes use light and lenses and can view living cells, but their resolution is limited to about 0.2 µm. Electron microscopes use a beam of electrons and have much higher resolution, so they show ultrastructure such as ribosomes, but specimens must be dead and in a vacuum.","Magnification = image size ÷ actual size. Both sizes must be in the same unit before you divide: 1 mm = 1000 µm and 1 µm = 1000 nm."],"workedExample":{"question":"A cell is 30 mm long in a micrograph taken at ×1500 magnification. What is its actual length in micrometres?","steps":["Rearrange: actual size = image size ÷ magnification.","Convert the image size: 30 mm = 30 × 1000 = 30 000 µm.","Actual size = 30 000 ÷ 1500 = 20 µm."],"answer":"20 µm"},"keyTerms":[{"term":"Eukaryotic cell","definition":"A cell with a nucleus and membrane-bound organelles."},{"term":"Prokaryotic cell","definition":"A cell with no nucleus; its DNA lies free in the cytoplasm, as in bacteria."},{"term":"Resolution","definition":"The ability to distinguish two points close together as separate."},{"term":"Magnification","definition":"How many times larger the image is than the real object: image size ÷ actual size."}],"misconceptions":[{"wrong":"Higher magnification always shows more detail.","right":"Detail depends on resolution. Magnifying beyond a microscope''s resolution just gives a bigger, blurred image."},{"wrong":"Bacteria have no DNA because they have no nucleus.","right":"Bacteria have DNA as a loop in the cytoplasm, and often plasmids too."},{"wrong":"You can divide sizes in mm by sizes in µm directly.","right":"Convert both sizes to the same unit before calculating."}],"retrieval":[{"q":"Which organelle is the site of aerobic respiration?","a":"The mitochondrion."},{"q":"Name three structures found in plant cells but not animal cells.","a":"Cellulose cell wall, permanent vacuole, chloroplasts."},{"q":"How many micrometres are in 1 mm?","a":"1000 µm."}],"specRefs":[{"board":"Pearson","code":"BTEC Nationals Applied Science (AAQ)","section":"Unit 1 Principles and Applications of Biology, learning aim A (cell structure and function)","url":"https://qualifications.pearson.com/en/qualifications/btec-nationals/applied-science-aaq.html"},{"board":"Pearson","code":"BTEC Nationals Applied Science (2016)","section":"Unit 1 Principles and Applications of Science I (B1 Cell structure and function)"}],"route":"btec","subject":"Applied Science"},"question_keys":["btec-appsci-cells-microscopy:cm1","btec-appsci-cells-microscopy:cm2","btec-appsci-cells-microscopy:cm3"],"version":"1.0"},{"course_id":"btec-business","topic_id":"btec-business-marketing-mix","course_title":"BTEC Business","title":"The marketing mix and target markets","content":{"summary":"The 4Ps, market segmentation and choosing a target market.","objectives":["Explain the 4Ps of the marketing mix","Describe ways to segment a market","Justify marketing decisions for a target market"],"explanation":["A target market is the particular group of customers a business aims to reach.","Businesses segment markets by factors such as age, income, location, lifestyle and behaviour so they can meet customer needs more closely.","The marketing mix (product, price, place and promotion) should fit together and suit the target market.","In assignments, use evidence about a real business and justify decisions: explain why each choice suits that business and its customers."],"workedExample":null,"keyTerms":[{"term":"Target market","definition":"The intended customer group for a product or service."},{"term":"Market segmentation","definition":"Dividing a market into groups with similar characteristics."},{"term":"Marketing mix","definition":"Product, price, place and promotion (the 4Ps)."},{"term":"USP","definition":"Unique selling point: what makes a product different from competitors."}],"misconceptions":[{"wrong":"Marketing just means advertising.","right":"Advertising is one part of promotion, which is one of the 4Ps."},{"wrong":"Describing the 4Ps is enough for higher grades.","right":"Higher grades usually require analysis and justified evaluation using evidence."}],"retrieval":[{"q":"Name the 4Ps.","a":"Product, price, place, promotion."},{"q":"What is a target market?","a":"The group of customers a business aims to reach."},{"q":"Give two ways to segment a market.","a":"E.g. age, income, location, lifestyle, gender, behaviour."}],"specRefs":[{"board":"Pearson","code":"BTEC Nationals Business","section":"Unit 2 Developing a Marketing Campaign"}],"route":"btec","subject":"Business"},"question_keys":["btec-business-marketing-mix:mk1","btec-business-marketing-mix:mk2"],"version":"1.0"},{"course_id":"btec-health-social-care","topic_id":"btec-hsc-care-values","course_title":"BTEC Health and Social Care","title":"Care values and person-centred practice","content":{"summary":"The values that guide care work and how they protect people who use services.","objectives":["Describe key care values such as dignity, respect, confidentiality and safeguarding","Explain person-centred care","Apply care values to a scenario"],"explanation":["Care values guide how practitioners support people. They include promoting dignity, respect and independence, maintaining confidentiality, safeguarding, promoting equality and effective communication.","Person-centred care puts the individual at the centre of decisions, respecting their preferences, beliefs and choices.","Confidentiality protects personal information and builds trust, but it has limits: if someone is at risk of harm, safeguarding procedures must be followed.","When applying values to a case study, explain what the practitioner does and how it benefits the individual."],"workedExample":null,"keyTerms":[{"term":"Confidentiality","definition":"Keeping personal information private and sharing it only when appropriate."},{"term":"Safeguarding","definition":"Protecting people''s health, wellbeing and rights, and preventing harm."},{"term":"Person-centred care","definition":"Care planned around the individual''s needs, wishes and choices."},{"term":"Empowerment","definition":"Supporting individuals to take control of their own lives."}],"misconceptions":[{"wrong":"Confidentiality means never sharing anything.","right":"Information must be shared when someone is at risk of harm, following procedures."},{"wrong":"Treating everyone the same is always fair.","right":"Equality means meeting different needs so people have fair access to care."}],"retrieval":[{"q":"Why is confidentiality important in care?","a":"It protects personal information and builds trust."},{"q":"When can confidentiality be broken?","a":"When there is a risk of harm, following safeguarding procedures."},{"q":"What is person-centred care?","a":"Care built around the individual''s needs, choices and preferences."}],"specRefs":[{"board":"Pearson","code":"BTEC Tech Award HSC","section":"Component 2 Health and Social Care Services and Values"}],"route":"btec","subject":"Health and Social Care"},"question_keys":["btec-hsc-care-values:cv1","btec-hsc-care-values:cv2"],"version":"1.0"},{"course_id":"btec-it","topic_id":"digital-cyber-threats","course_title":"BTEC Information Technology","title":"Cyber security threats and protection","content":{"summary":"Common threats such as phishing and malware, and how organisations protect systems.","objectives":["Describe common cyber threats","Explain technical and human protection methods","Explain authentication including multi-factor authentication"],"explanation":["Common threats include malware (viruses, worms, ransomware), phishing and other social engineering. Vulnerabilities such as weak passwords and unpatched software make these attacks more likely to succeed.","Phishing uses messages that pretend to be trustworthy to trick people into revealing information or clicking harmful links.","Technical protections include firewalls, anti-malware, encryption, access controls, backups and keeping software updated.","Human protections include staff training, clear policies and reporting procedures.","Multi-factor authentication (MFA) requires two or more different types of evidence (something you know, have or are), so a stolen password alone is not enough."],"workedExample":null,"keyTerms":[{"term":"Phishing","definition":"Fraudulent messages designed to trick people into revealing information."},{"term":"Ransomware","definition":"Malware that encrypts data and demands payment."},{"term":"Encryption","definition":"Scrambling data so only authorised people with a key can read it."},{"term":"MFA","definition":"Multi-factor authentication: using more than one type of evidence to verify identity."}],"misconceptions":[{"wrong":"A firewall stops all cyber attacks.","right":"Firewalls filter network traffic but cannot stop phishing or insider threats alone."},{"wrong":"Two passwords count as MFA.","right":"MFA needs different factor types, e.g. a password plus a phone code."}],"retrieval":[{"q":"What is phishing?","a":"Fraudulent messages that trick people into revealing information or clicking harmful links."},{"q":"Name the three factor types in MFA.","a":"Something you know, have and are."},{"q":"Give two technical protections.","a":"E.g. firewalls, anti-malware, encryption, backups, updates, access controls."}],"specRefs":[{"board":"Pearson","code":"BTEC Tech Award DIT","section":"Component 3 Effective Digital Working Practices"}],"route":"btec","subject":"Information Technology"},"question_keys":["digital-cyber-threats:cy1","digital-cyber-threats:cy2"],"version":"1.1"}]'::jsonb) on conflict(course_id,topic_id) do update set course_title=excluded.course_title,title=excluded.title,content=excluded.content,question_keys=excluded.question_keys,version=excluded.version;
insert into public.subject_quest_catalogue select * from jsonb_populate_recordset(null::public.subject_quest_catalogue,'[{"course_id":"btec-sport","topic_id":"btec-sport-skeletal-muscular","course_title":"BTEC Sport","title":"Joints, antagonistic pairs and muscle fibre types","content":{"summary":"How synovial joints, muscles and fibre types work together to produce movement in sport.","objectives":["Identify types of synovial joint and the movements they allow","Explain how antagonistic muscle pairs produce movement","Describe concentric, eccentric and isometric contractions","Compare type I, type IIa and type IIx muscle fibres"],"explanation":["Synovial joints are freely movable joints. Types include ball and socket (shoulder, hip), hinge (elbow, knee), pivot (between the first two vertebrae in the neck), condyloid (wrist), saddle (base of the thumb) and gliding (between the carpals). The type determines the range of movement.","Joint movements include flexion (decreasing the angle at a joint), extension (increasing it), abduction (away from the midline), adduction (towards the midline), rotation and circumduction. At the ankle, pointing the toes is plantarflexion and pulling them up is dorsiflexion.","Muscles can only pull, so they work in antagonistic pairs. The agonist is the muscle that contracts to cause the movement, the antagonist relaxes to allow it, and the fixator stabilises the origin of the agonist. Examples include biceps and triceps at the elbow, and quadriceps and hamstrings at the knee.","In a concentric contraction the muscle shortens under tension; in an eccentric contraction it lengthens under tension, controlling a movement; in an isometric contraction it produces tension without changing length, as when holding a plank.","Type I (slow twitch) fibres contract slowly, resist fatigue and suit endurance events. Type IIa fibres are fast and fairly fatigue-resistant, suiting events such as the 800 m. Type IIx fibres contract fastest and most forcefully but fatigue quickly, suiting sprinting and jumping."],"workedExample":{"question":"Analyse the upward phase of a bicep curl: name the joint type, the movement, the agonist and antagonist, and the type of contraction.","steps":["The elbow is a hinge joint.","Raising the weight decreases the angle at the elbow, so the movement is flexion.","The biceps brachii contracts to cause the movement, so it is the agonist; the triceps brachii relaxes, so it is the antagonist.","The biceps shortens while under tension, so the contraction is concentric.","In the lowering phase the biceps lengthens while still under tension to control the weight, which is an eccentric contraction."],"answer":"Hinge joint, flexion, biceps agonist (concentric) and triceps antagonist"},"keyTerms":[{"term":"Synovial joint","definition":"A freely movable joint with a joint capsule, synovial membrane and synovial fluid."},{"term":"Agonist","definition":"The muscle that contracts to cause a movement."},{"term":"Antagonist","definition":"The muscle that relaxes to allow the agonist to move a joint."},{"term":"Eccentric contraction","definition":"A contraction in which the muscle lengthens under tension."}],"misconceptions":[{"wrong":"Muscles can push bones as well as pull them.","right":"Muscles can only pull. Movement back the other way needs the opposite muscle of the pair."},{"wrong":"When lowering a weight slowly, the triceps does the work.","right":"The biceps controls the lowering by contracting eccentrically; gravity provides the downward force."},{"wrong":"Type IIx fibres are best for all sports because they are strongest.","right":"They fatigue quickly, so endurance athletes rely mainly on type I fibres."}],"retrieval":[{"q":"Name a ball and socket joint.","a":"The shoulder or the hip."},{"q":"What is the antagonist to the quadriceps when the knee extends?","a":"The hamstrings."},{"q":"Which fibre type is most fatigue-resistant?","a":"Type I (slow twitch)."}],"specRefs":[{"board":"Pearson","code":"BTEC Nationals Sport (2016)","section":"Unit 1 Anatomy and Physiology (A3 Joints; B3 Antagonistic muscle pairs; B4–B5 contraction and fibre types)","url":"https://qualifications.pearson.com/content/dam/pdf/BTEC-Nationals/Sport/20161/specification-and-sample-assessments/btec-l3-national-cert-in-sport-spec.pdf"}],"route":"btec","subject":"Sport"},"question_keys":["btec-sport-skeletal-muscular:sk1","btec-sport-skeletal-muscular:sk2","btec-sport-skeletal-muscular:sk3"],"version":"1.0"},{"course_id":"btec-engineering","topic_id":"btec-eng-dc-circuits","course_title":"BTEC Engineering","title":"DC circuits: Ohm''s law, resistor networks and power","content":{"summary":"Charge, current, voltage and resistance, combining resistors, and calculating power.","objectives":["Use Q = It and V = IR in calculations","Find the total resistance of series, parallel and mixed networks","Apply Kirchhoff''s current and voltage laws","Calculate electrical power in different forms"],"explanation":["Current is the rate of flow of charge, I = Q ÷ t, measured in amperes (A). Conventional current flows from positive to negative. Potential difference (voltage) is the energy transferred per unit charge, measured in volts (V).","Ohm''s law states that, for a conductor at constant temperature, current is proportional to potential difference: V = IR, where R is resistance in ohms (Ω).","Resistors in series carry the same current, and R_T = R₁ + R₂ + R₃ + … Resistors in parallel share the same potential difference, and 1/R_T = 1/R₁ + 1/R₂ + … The total resistance of a parallel group is always less than its smallest resistor.","Kirchhoff''s current law: the total current entering a junction equals the total current leaving it. Kirchhoff''s voltage law: around any closed loop, the sum of the EMFs equals the sum of the potential differences.","Power is the rate of energy transfer: P = IV = I²R = V²/R, measured in watts (W). Efficiency = useful output power ÷ total input power × 100%. Always show the formula, substitution and units in exam answers."],"workedExample":{"question":"A 12 V DC supply is connected to a 4 Ω resistor in series with a parallel pair of 6 Ω and 12 Ω resistors. Find the total resistance, the supply current, the current in each parallel branch and the total power.","steps":["Parallel pair: 1/R = 1/6 + 1/12 = 3/12, so R = 4 Ω.","Total resistance: R_T = 4 + 4 = 8 Ω.","Supply current: I = V ÷ R_T = 12 ÷ 8 = 1.5 A.","PD across the 4 Ω resistor = 1.5 × 4 = 6 V, so the PD across the parallel pair = 12 − 6 = 6 V (Kirchhoff''s voltage law).","Branch currents: 6 ÷ 6 = 1.0 A and 6 ÷ 12 = 0.5 A, which add to 1.5 A (Kirchhoff''s current law). ✓","Total power: P = IV = 1.5 × 12 = 18 W."],"answer":"R_T = 8 Ω, I = 1.5 A, branch currents 1.0 A and 0.5 A, P = 18 W"},"keyTerms":[{"term":"Current","definition":"The rate of flow of charge, I = Q ÷ t, measured in amperes."},{"term":"Potential difference","definition":"The energy transferred per unit charge between two points, measured in volts."},{"term":"Resistance","definition":"Opposition to current: the ratio V ÷ I, measured in ohms (Ω)."},{"term":"Power","definition":"The rate of energy transfer, measured in watts: P = IV."}],"misconceptions":[{"wrong":"Adding a resistor in parallel increases the total resistance.","right":"It adds another path for current, so the total resistance falls."},{"wrong":"Current is used up as it passes through a resistor.","right":"Current is the same everywhere in a series circuit. Energy is transferred, not charge."}],"retrieval":[{"q":"State Ohm''s law as an equation.","a":"V = IR."},{"q":"What is the total resistance of 10 Ω and 10 Ω in parallel?","a":"5 Ω."},{"q":"State Kirchhoff''s current law.","a":"The total current into a junction equals the total current out of it."}],"specRefs":[{"board":"Pearson","code":"BTEC Nationals Engineering (AAQ) 610/3962/7","section":"Unit 1 Engineering Principles (C1 Direct current electricity and circuits)","url":"https://qualifications.pearson.com/en/qualifications/btec-nationals/engineering-aaq.html"}],"route":"btec","subject":"Engineering"},"question_keys":["btec-eng-dc-circuits:dc1","btec-eng-dc-circuits:dc2","btec-eng-dc-circuits:dc3"],"version":"1.0"},{"course_id":"btec-creative-media","topic_id":"btec-media-representation","course_title":"BTEC Creative Media","title":"Media representation and audience readings","content":{"summary":"How media products construct representations, and how audiences decode them.","objectives":["Explain what a representation is and why it is always constructed","Analyse media language using denotation, connotation and anchorage","Describe preferred, negotiated and oppositional readings","Evaluate the effects of stereotypes and other representations"],"explanation":["A representation is the way a media product presents people, groups, places or ideas. It is never a neutral window on reality: producers select what to include and leave out, and construct it through camera, lighting, editing, sound and design.","Semiotics analyses media language as signs. Denotation is what a sign literally shows; connotation is the meanings associated with it. A red rose denotes a flower but can connote romance. Anchorage is text, such as a caption or slogan, that fixes one intended meaning of an image.","Producers encode a message, and audiences decode it. Stuart Hall described three main readings: a preferred (dominant) reading accepts the intended message; a negotiated reading accepts parts of it; an oppositional reading rejects it. The same product can be read differently depending on the audience''s age, background and experiences.","A stereotype is an oversimplified representation of a group, reduced to a few traits. Stereotypes can make meaning quick to grasp, but they can also reinforce prejudice and exclude people. Look for presence and absence: who is shown, who is missing, and who has power in the product?","In analysis, link every technical choice to a meaning, and every meaning to its possible effect on the audience. Use accurate terminology, but always explain what the term shows."],"workedExample":{"question":"An advert for a car shows a woman in a suit driving alone through a city at dawn, with the slogan ''Your day. Your rules.'' Analyse its representation of women.","steps":["Denotation: a woman in business clothing drives a car through an empty city at sunrise.","Connotation: the suit and empty road suggest professional success, independence and control; dawn connotes ambition and a fresh start.","Anchorage: the slogan fixes the meaning around personal freedom and choice.","Representation: the woman is constructed as confident and in charge, challenging older stereotypes of women as passengers in car adverts.","Audience: the preferred reading is aspirational, but an oppositional reader might see independence being used simply to sell a product."],"answer":"A counter-stereotypical representation of an independent professional woman, anchored by the slogan, with more than one possible audience reading"},"keyTerms":[{"term":"Representation","definition":"How the media constructs and presents people, groups, places or ideas."},{"term":"Connotation","definition":"The associated or implied meanings of a sign."},{"term":"Anchorage","definition":"Text that fixes the intended meaning of an image, such as a caption."},{"term":"Oppositional reading","definition":"When an audience rejects the producer''s intended message."}],"misconceptions":[{"wrong":"Documentaries and news show reality exactly as it is.","right":"All media products are constructed through selection and editing, so all are representations."},{"wrong":"Every audience member reads a product in the same way.","right":"Audiences can make preferred, negotiated or oppositional readings."},{"wrong":"Stereotypes are always negative.","right":"Some are positive, but all oversimplify, which can still be limiting or harmful."}],"retrieval":[{"q":"What is the difference between denotation and connotation?","a":"Denotation is the literal meaning; connotation is the associated meaning."},{"q":"Name the three main audience readings.","a":"Preferred (dominant), negotiated and oppositional."},{"q":"What does anchorage do?","a":"Fixes the intended meaning of an image."}],"specRefs":[{"board":"Pearson","code":"BTEC Nationals Creative Digital Media Production (2016)","section":"Unit 1 Media Representations (B1 Constructing messages; B2 Audience decoding; B3 Semiotics)","url":"https://qualifications.pearson.com/content/dam/pdf/BTEC-Nationals/creative-digital-media-production/2016/specification-and-sample-assessments/btec-l3-nat-extcert-in-creative-digital-media-prod-spec.pdf"}],"route":"btec","subject":"Creative Media"},"question_keys":["btec-media-representation:mr1","btec-media-representation:mr2","btec-media-representation:mr3"],"version":"1.0"},{"course_id":"tlevel-digital-production","topic_id":"digital-cyber-threats","course_title":"T Level in Digital Software Development","title":"Cyber security threats and protection","content":{"summary":"Common threats such as phishing and malware, and how organisations protect systems.","objectives":["Describe common cyber threats","Explain technical and human protection methods","Explain authentication including multi-factor authentication"],"explanation":["Common threats include malware (viruses, worms, ransomware), phishing and other social engineering. Vulnerabilities such as weak passwords and unpatched software make these attacks more likely to succeed.","Phishing uses messages that pretend to be trustworthy to trick people into revealing information or clicking harmful links.","Technical protections include firewalls, anti-malware, encryption, access controls, backups and keeping software updated.","Human protections include staff training, clear policies and reporting procedures.","Multi-factor authentication (MFA) requires two or more different types of evidence (something you know, have or are), so a stolen password alone is not enough."],"workedExample":null,"keyTerms":[{"term":"Phishing","definition":"Fraudulent messages designed to trick people into revealing information."},{"term":"Ransomware","definition":"Malware that encrypts data and demands payment."},{"term":"Encryption","definition":"Scrambling data so only authorised people with a key can read it."},{"term":"MFA","definition":"Multi-factor authentication: using more than one type of evidence to verify identity."}],"misconceptions":[{"wrong":"A firewall stops all cyber attacks.","right":"Firewalls filter network traffic but cannot stop phishing or insider threats alone."},{"wrong":"Two passwords count as MFA.","right":"MFA needs different factor types, e.g. a password plus a phone code."}],"retrieval":[{"q":"What is phishing?","a":"Fraudulent messages that trick people into revealing information or clicking harmful links."},{"q":"Name the three factor types in MFA.","a":"Something you know, have and are."},{"q":"Give two technical protections.","a":"E.g. firewalls, anti-malware, encryption, backups, updates, access controls."}],"specRefs":[{"board":"Pearson","code":"BTEC Tech Award DIT","section":"Component 3 Effective Digital Working Practices"}],"route":"tlevel","subject":"Digital Software Development","foundationFrom":"BTEC Information Technology"},"question_keys":["digital-cyber-threats:cy1","digital-cyber-threats:cy2"],"version":"1.1"},{"course_id":"tlevel-digital-support","topic_id":"digital-cyber-threats","course_title":"T Level in Digital Support and Security","title":"Cyber security threats and protection","content":{"summary":"Common threats such as phishing and malware, and how organisations protect systems.","objectives":["Describe common cyber threats","Explain technical and human protection methods","Explain authentication including multi-factor authentication"],"explanation":["Common threats include malware (viruses, worms, ransomware), phishing and other social engineering. Vulnerabilities such as weak passwords and unpatched software make these attacks more likely to succeed.","Phishing uses messages that pretend to be trustworthy to trick people into revealing information or clicking harmful links.","Technical protections include firewalls, anti-malware, encryption, access controls, backups and keeping software updated.","Human protections include staff training, clear policies and reporting procedures.","Multi-factor authentication (MFA) requires two or more different types of evidence (something you know, have or are), so a stolen password alone is not enough."],"workedExample":null,"keyTerms":[{"term":"Phishing","definition":"Fraudulent messages designed to trick people into revealing information."},{"term":"Ransomware","definition":"Malware that encrypts data and demands payment."},{"term":"Encryption","definition":"Scrambling data so only authorised people with a key can read it."},{"term":"MFA","definition":"Multi-factor authentication: using more than one type of evidence to verify identity."}],"misconceptions":[{"wrong":"A firewall stops all cyber attacks.","right":"Firewalls filter network traffic but cannot stop phishing or insider threats alone."},{"wrong":"Two passwords count as MFA.","right":"MFA needs different factor types, e.g. a password plus a phone code."}],"retrieval":[{"q":"What is phishing?","a":"Fraudulent messages that trick people into revealing information or clicking harmful links."},{"q":"Name the three factor types in MFA.","a":"Something you know, have and are."},{"q":"Give two technical protections.","a":"E.g. firewalls, anti-malware, encryption, backups, updates, access controls."}],"specRefs":[{"board":"Pearson","code":"BTEC Tech Award DIT","section":"Component 3 Effective Digital Working Practices"}],"route":"tlevel","subject":"Digital Support and Security","foundationFrom":"BTEC Information Technology"},"question_keys":["digital-cyber-threats:cy1","digital-cyber-threats:cy2"],"version":"1.1"},{"course_id":"tlevel-health","topic_id":"tlevel-health-infection-control","course_title":"T Level in Health","title":"Infection prevention and control","content":{"summary":"The chain of infection and standard infection control precautions used in health settings.","objectives":["Describe the chain of infection","Explain standard infection control precautions","Describe effective hand hygiene"],"explanation":["The chain of infection links an infectious agent, a reservoir, a portal of exit, a mode of transmission, a portal of entry and a susceptible host. Breaking any link can prevent spread.","Standard infection control precautions (SICPs) include patient placement and assessment for infection risk, hand hygiene, respiratory and cough hygiene, personal protective equipment (PPE), safe management of the care environment and of care equipment, safe management of linen, safe management of blood and body fluids, safe disposal of waste (including sharps) and occupational safety, including preventing sharps injuries.","Hand hygiene is one of the most effective ways to reduce the spread of infection. Follow your setting''s policy on when to use soap and water or alcohol hand rub.","Always follow your placement setting''s policies and procedures, and ask your supervisor if you are unsure."],"workedExample":null,"keyTerms":[{"term":"Chain of infection","definition":"The sequence of links needed for an infection to spread."},{"term":"PPE","definition":"Personal protective equipment such as gloves, aprons and masks."},{"term":"Susceptible host","definition":"A person who can become infected."},{"term":"Standard infection control precautions (SICPs)","definition":"Basic infection control measures used with everyone in care settings."}],"misconceptions":[{"wrong":"Wearing gloves replaces hand washing.","right":"Hand hygiene is still needed before and after glove use."},{"wrong":"Precautions are only for people known to be infectious.","right":"Standard infection control precautions apply to everyone, every time."}],"retrieval":[{"q":"How can the spread of infection be prevented?","a":"By breaking any link in the chain of infection."},{"q":"Name three standard infection control precautions (SICPs).","a":"E.g. hand hygiene, PPE, waste management, sharps safety, cleaning."},{"q":"Does wearing gloves remove the need for hand hygiene?","a":"No."}],"specRefs":[{"board":"Pearson","code":"T Level Health 610/7438/X","section":"Content area 2 (2.5.1 PPE and hand hygiene)","url":"https://qualifications.pearson.com/content/dam/pdf/TLevels/health/2026/specification-and-sample-assessment-materials/t-level-health-spec.pdf"},{"board":"NHS England","code":"NIPCM","section":"Chapter 1 Standard infection control precautions","url":"https://www.england.nhs.uk/national-infection-prevention-and-control-manual-nipcm-for-england/chapter-1-standard-infection-control-precautions-sicps/"}],"route":"tlevel","subject":"Health"},"question_keys":["tlevel-health-infection-control:ic1","tlevel-health-infection-control:ic2"],"version":"1.1"},{"course_id":"tlevel-healthcare-science","topic_id":"tlevel-health-infection-control","course_title":"T Level in Healthcare Science","title":"Infection prevention and control","content":{"summary":"The chain of infection and standard infection control precautions used in health settings.","objectives":["Describe the chain of infection","Explain standard infection control precautions","Describe effective hand hygiene"],"explanation":["The chain of infection links an infectious agent, a reservoir, a portal of exit, a mode of transmission, a portal of entry and a susceptible host. Breaking any link can prevent spread.","Standard infection control precautions (SICPs) include patient placement and assessment for infection risk, hand hygiene, respiratory and cough hygiene, personal protective equipment (PPE), safe management of the care environment and of care equipment, safe management of linen, safe management of blood and body fluids, safe disposal of waste (including sharps) and occupational safety, including preventing sharps injuries.","Hand hygiene is one of the most effective ways to reduce the spread of infection. Follow your setting''s policy on when to use soap and water or alcohol hand rub.","Always follow your placement setting''s policies and procedures, and ask your supervisor if you are unsure."],"workedExample":null,"keyTerms":[{"term":"Chain of infection","definition":"The sequence of links needed for an infection to spread."},{"term":"PPE","definition":"Personal protective equipment such as gloves, aprons and masks."},{"term":"Susceptible host","definition":"A person who can become infected."},{"term":"Standard infection control precautions (SICPs)","definition":"Basic infection control measures used with everyone in care settings."}],"misconceptions":[{"wrong":"Wearing gloves replaces hand washing.","right":"Hand hygiene is still needed before and after glove use."},{"wrong":"Precautions are only for people known to be infectious.","right":"Standard infection control precautions apply to everyone, every time."}],"retrieval":[{"q":"How can the spread of infection be prevented?","a":"By breaking any link in the chain of infection."},{"q":"Name three standard infection control precautions (SICPs).","a":"E.g. hand hygiene, PPE, waste management, sharps safety, cleaning."},{"q":"Does wearing gloves remove the need for hand hygiene?","a":"No."}],"specRefs":[{"board":"Pearson","code":"T Level Health 610/7438/X","section":"Content area 2 (2.5.1 PPE and hand hygiene)","url":"https://qualifications.pearson.com/content/dam/pdf/TLevels/health/2026/specification-and-sample-assessment-materials/t-level-health-spec.pdf"},{"board":"NHS England","code":"NIPCM","section":"Chapter 1 Standard infection control precautions","url":"https://www.england.nhs.uk/national-infection-prevention-and-control-manual-nipcm-for-england/chapter-1-standard-infection-control-precautions-sicps/"}],"route":"tlevel","subject":"Healthcare Science","foundationFrom":"T Level in Health"},"question_keys":["tlevel-health-infection-control:ic1","tlevel-health-infection-control:ic2"],"version":"1.1"},{"course_id":"tlevel-science","topic_id":"tlevel-science-lab-safety","course_title":"T Level in Science","title":"Working safely in the laboratory","content":{"summary":"COSHH, risk assessment, the hierarchy of control and GB CLP hazard pictograms.","objectives":["Explain the purpose of COSHH and a COSHH risk assessment","Distinguish between a hazard and a risk","Apply the hierarchy of control, with PPE as the last resort","Recognise GB CLP hazard pictograms and use safety data sheets"],"explanation":["The Control of Substances Hazardous to Health Regulations 2002 (COSHH) require employers to control exposure to hazardous substances. In a laboratory this means identifying the hazards, assessing the risks, putting controls in place, making sure they are used and maintained, and giving staff information and training.","A hazard is something with the potential to cause harm, such as a corrosive acid. A risk is the likelihood that harm will actually happen, together with how serious it would be. A risk assessment records the hazards, who might be harmed, the controls and what to do in an emergency.","Use the hierarchy of control in order: eliminate the hazard, substitute something less hazardous (for example a more dilute solution), use engineering controls (such as a fume cupboard), use administrative controls (standard operating procedures, training, signage), and finally personal protective equipment (PPE) such as goggles, lab coats and gloves.","Chemical labels in Great Britain use GB CLP hazard pictograms: a red-bordered diamond on a white background. Examples include the flame (flammable), corrosion, skull and crossbones (acute toxicity), exclamation mark and gas cylinder. The supplier''s safety data sheet (SDS) gives detailed hazard, handling, storage and first-aid information.","Good laboratory practice also means following standard operating procedures (SOPs) exactly, labelling all containers, keeping clear records, disposing of waste by the correct route and reporting accidents and near misses."],"workedExample":{"question":"A technician needs to prepare 1 mol dm⁻³ hydrochloric acid from a concentrated stock solution. Outline the key points of the risk assessment.","steps":["Hazard: concentrated hydrochloric acid is corrosive (corrosion pictogram) and gives off irritating fumes.","Who is at risk: the technician and anyone nearby, through skin or eye contact or by breathing in fumes.","Controls, following the hierarchy: work in a fume cupboard (engineering), follow the SOP and always add acid to water, not water to acid (administrative), and wear splash-proof goggles, a lab coat and suitable gloves (PPE).","Emergency: know where the eyewash station is and how to deal with spills using the correct spill kit.","Record the assessment, check the safety data sheet and label the diluted solution with its name, concentration, hazard and date."],"answer":"Identify the corrosive hazard, apply controls in hierarchy order with PPE last, and plan for spills and eye contact"},"keyTerms":[{"term":"Hazard","definition":"Something with the potential to cause harm."},{"term":"Risk","definition":"The likelihood that a hazard will cause harm, combined with how severe the harm could be."},{"term":"COSHH","definition":"The Control of Substances Hazardous to Health Regulations 2002."},{"term":"Safety data sheet (SDS)","definition":"A supplier''s document giving hazard, handling, storage and emergency information for a chemical."}],"misconceptions":[{"wrong":"Wearing PPE is the most important control measure.","right":"PPE is the last resort. Remove or reduce the hazard first, then use engineering and administrative controls."},{"wrong":"Hazard and risk mean the same thing.","right":"A hazard can cause harm; risk is how likely and how serious that harm is in a given situation."},{"wrong":"A risk assessment is done once and then filed.","right":"It should be reviewed when the procedure, substances or people change, or after an incident."}],"retrieval":[{"q":"What does COSHH stand for?","a":"Control of Substances Hazardous to Health (Regulations 2002)."},{"q":"What is the least preferred level of the hierarchy of control?","a":"Personal protective equipment (PPE)."},{"q":"What shape and colour are GB CLP hazard pictograms?","a":"A diamond with a red border and a white background."}],"specRefs":[{"board":"Pearson","code":"T Level Science 610/7439/1","section":"Core: Health and safety in a laboratory environment","url":"https://qualifications.pearson.com/content/dam/pdf/TLevels/science/2026/administration/qualification-description-t-level-technical-qualification-in-science.pdf"},{"board":"HSE","code":"COSHH","section":"Control of Substances Hazardous to Health Regulations 2002","url":"https://www.hse.gov.uk/coshh/"}],"route":"tlevel","subject":"Science"},"question_keys":["tlevel-science-lab-safety:ls1","tlevel-science-lab-safety:ls2","tlevel-science-lab-safety:ls3"],"version":"1.0"},{"course_id":"tlevel-education-early-years","topic_id":"tlevel-eey-child-development","course_title":"T Level in Education and Early Years","title":"Patterns of child development","content":{"summary":"Areas of development, sequence and rate, and typical physical, cognitive and social development.","objectives":["Describe the main areas of child development","Explain the difference between the sequence and the rate of development","Distinguish between gross and fine motor skills","Explain why development should be viewed holistically"],"explanation":["Development is usually described in areas: physical (gross and fine motor skills), cognitive (thinking, memory, problem solving and perception), communication and language, and social and emotional (attachments, expressing feelings, self-regulation and friendships).","Gross motor skills use large movements of the whole body, such as crawling, walking, running and climbing. Fine motor skills use smaller, more precise movements, such as a pincer grasp, threading beads or holding a pencil.","Most children develop in a broadly predictable sequence (for example, sitting before standing and standing before walking), but the rate varies a lot. The age at which children walk independently differs widely; many are still learning up to about 18 months, and that can be entirely typical.","Areas of development are interconnected, so practitioners look at the whole child. A toddler who starts walking can explore more, which supports cognitive development and new language; a child with a secure attachment has the confidence to play with other children.","Practitioners need to understand development from birth to 19 years. In adolescence, physical changes at puberty happen alongside growing independence, abstract thinking and changing peer relationships. Practitioners use observation to track progress against expected patterns and to plan next steps, sharing concerns with the setting''s SENCo or lead practitioner when needed."],"workedExample":{"question":"A practitioner observes a two-year-old kicking a ball, turning the pages of a board book one at a time, naming animals in the book and handing a toy to a friend. Sort the observations into areas of development.","steps":["Kicking a ball uses large whole-body movements: physical development (gross motor).","Turning single pages needs small, controlled hand movements: physical development (fine motor).","Naming animals shows vocabulary and recognition: communication and language, and cognitive development.","Handing a toy to a friend shows sharing and early friendship: social and emotional development.","Note that one activity (sharing the book) can show several areas at once, which is why development is viewed holistically."],"answer":"Gross motor, fine motor, communication and language (with cognitive), and social and emotional development"},"keyTerms":[{"term":"Gross motor skills","definition":"Skills using large movements of the whole body."},{"term":"Fine motor skills","definition":"Skills using small, precise movements, especially of the hands."},{"term":"Sequence of development","definition":"The broadly predictable order in which skills develop."},{"term":"Holistic development","definition":"The idea that all areas of development are linked and affect one another."}],"misconceptions":[{"wrong":"All children should reach each milestone at exactly the same age.","right":"The sequence is broadly similar, but the rate varies. Milestones are guides, not deadlines."},{"wrong":"Areas of development can be supported separately.","right":"They are interconnected, so one activity often supports several areas at once."}],"retrieval":[{"q":"Give one example of a fine motor skill.","a":"E.g. pincer grasp, threading beads, holding a pencil."},{"q":"What is the difference between sequence and rate of development?","a":"Sequence is the order skills appear; rate is how quickly they appear."},{"q":"Name the four broad areas of development.","a":"Physical, cognitive, communication and language, social and emotional."}],"specRefs":[{"board":"NCFE","code":"T Level Education and Early Years 610/5748/4","section":"Element 5 Child development (5.1 How characteristics of cognitive, physical, social and emotional learning typically develop from birth to 19 years)","url":"https://www.ncfe.org.uk/media/ddyd0f2j/610-5748-4-qualification-specification-v2-0.pdf"},{"board":"NCFE","code":"T Level Education and Early Years 603/5829/4","section":"Element 7 Child development (students who started before 2025)","url":"https://www.ncfe.org.uk/media/gdteldbv/603-5829-4-qualification-specification.pdf"}],"route":"tlevel","subject":"Education and Early Years"},"question_keys":["tlevel-eey-child-development:cd1","tlevel-eey-child-development:cd2","tlevel-eey-child-development:cd3"],"version":"1.0"},{"course_id":"tlevel-construction-design","topic_id":"tlevel-construction-building-regs","course_title":"T Level in Design, Surveying and Planning for Construction","title":"Building Regulations and energy efficiency","content":{"summary":"What the Building Regulations and Approved Documents do, how compliance is checked, and heat loss through the building fabric.","objectives":["Explain the purpose of the Building Regulations and Approved Documents","Identify the main Parts, including B, L and M","Describe who checks compliance in England","Calculate fabric heat loss using U-values"],"explanation":["In England, the Building Regulations 2010 set minimum standards for the design and construction of buildings, covering areas such as structure, fire safety, ventilation, drainage, energy efficiency and access. They apply to most new buildings, extensions and many alterations.","Approved Documents give practical guidance on how to meet each Part: for example Part A (structure), Part B (fire safety), Part L (conservation of fuel and power), Part M (access to and use of buildings) and Part O (overheating). Following an Approved Document is not the only way to comply, but it is the usual way to show compliance.","Compliance is checked by a building control body: either the local authority or a registered building control approver. For higher-risk buildings, such as many tall residential buildings, the Building Safety Regulator is the building control authority. Failing to comply can lead to enforcement and prosecution.","Part L limits energy use and carbon emissions. The U-value of an element (in W/m²K) is the rate of heat loss through 1 m² for each 1 K (1 °C) difference between inside and outside. A lower U-value means better insulation. Fabric heat loss Q = U × A × ΔT.","Sustainable design also considers embodied carbon in materials, renewable energy, water efficiency and whole-life performance. Tools include Energy Performance Certificates (EPCs) and voluntary assessment schemes such as BREEAM and the Home Quality Mark."],"workedExample":{"question":"A 40 m² external wall has a U-value of 0.26 W/m²K. It is upgraded to 0.18 W/m²K. With 20 °C inside and 0 °C outside, find the heat loss before and after, and the percentage reduction.","steps":["ΔT = 20 − 0 = 20 K.","Before: Q = U × A × ΔT = 0.26 × 40 × 20 = 208 W.","After: Q = 0.18 × 40 × 20 = 144 W.","Reduction = 208 − 144 = 64 W.","Percentage reduction = 64 ÷ 208 × 100 = 30.8% (to 1 d.p.)."],"answer":"208 W before, 144 W after: a 64 W (30.8%) reduction"},"keyTerms":[{"term":"Building Regulations","definition":"Legal minimum standards for the design and construction of buildings."},{"term":"Approved Document","definition":"Government guidance showing ways to meet a Part of the Building Regulations."},{"term":"U-value","definition":"The rate of heat transfer through 1 m² of an element per 1 K temperature difference, in W/m²K."},{"term":"Embodied carbon","definition":"The carbon emissions from making, transporting and installing a material or product."}],"misconceptions":[{"wrong":"A higher U-value means better insulation.","right":"A lower U-value means less heat is lost, so it insulates better."},{"wrong":"Planning permission and Building Regulations approval are the same thing.","right":"Planning controls use and appearance of development; Building Regulations control how it is built. A project may need one, both or neither."},{"wrong":"Approved Documents are the law itself.","right":"The Regulations are the law. Approved Documents are guidance on ways to comply with them."}],"retrieval":[{"q":"Which Part of the Building Regulations covers conservation of fuel and power?","a":"Part L."},{"q":"Write the equation for fabric heat loss.","a":"Q = U × A × ΔT."},{"q":"Who can act as the building control body for an ordinary project in England?","a":"The local authority or a registered building control approver."}],"specRefs":[{"board":"Pearson","code":"T Level Design, Surveying and Planning 610/5310/7","section":"CK10 Sustainability (CK10.4 Approved Document L); CK14 Law (CK14.6 Building Regulations)","url":"https://qualifications.pearson.com/content/dam/pdf/TLevels/construction/2025/specification-and-sample-assessments/tlevel-design-surveying-and-planning-for-construction-gen2.pdf"},{"board":"MHCLG","code":"Approved Documents","section":"Parts A–T and Regulation 7","url":"https://www.gov.uk/government/collections/approved-documents"}],"route":"tlevel","subject":"Design, Surveying and Planning for Construction"},"question_keys":["tlevel-construction-building-regs:br1","tlevel-construction-building-regs:br2","tlevel-construction-building-regs:br3"],"version":"1.0"}]'::jsonb) on conflict(course_id,topic_id) do update set course_title=excluded.course_title,title=excluded.title,content=excluded.content,question_keys=excluded.question_keys,version=excluded.version;
insert into public.subject_quest_catalogue select * from jsonb_populate_recordset(null::public.subject_quest_catalogue,'[{"course_id":"tlevel-onsite-construction","topic_id":"tlevel-onsite-cdm-2015","course_title":"T Level in Onsite Construction","title":"Construction health and safety: CDM 2015","content":{"summary":"The duty holders under CDM 2015, when projects must be notified, and the construction phase plan.","objectives":["Describe the duty holders under CDM 2015 and their main duties","Explain when a principal designer and principal contractor must be appointed","Apply the HSE notification thresholds","Explain the purpose of the construction phase plan and site induction"],"explanation":["The Construction (Design and Management) Regulations 2015 (CDM 2015) are made under the Health and Safety at Work etc. Act 1974. They aim to make sure health and safety is planned and managed through every stage of a construction project, from design to completion.","The duty holders are the client (commercial or domestic), designers, the principal designer, contractors, the principal contractor and workers. Everyone must co-operate, share information and only take on work they have the skills, knowledge and experience to do safely.","Where there is, or is likely to be, more than one contractor, the client must appoint in writing a principal designer (to control the pre-construction phase) and a principal contractor (to control the construction phase). If the client does not, the client must carry out those duties.","A project is notifiable to HSE (using form F10) if the construction work is expected to last longer than 30 working days and have more than 20 workers working at the same time at any point, or to exceed 500 person days. The client has the duty to notify.","Every project needs a written construction phase plan, drawn up by the principal contractor (or by the only contractor) before the construction phase begins. The principal contractor must also make sure every worker has a site-specific induction. Day-to-day controls include risk assessments, method statements and permits to work."],"workedExample":{"question":"A shop owner hires a builder, an electrician and a plasterer to refurbish a shop. The work will last 40 working days with up to 25 workers on site at the same time. What does CDM 2015 require?","steps":["The shop owner is a commercial client because the work is for a business.","There is more than one contractor, so the client must appoint a principal designer and a principal contractor in writing.","The work lasts longer than 30 working days and has more than 20 workers at the same time, so it is notifiable to HSE.","The client must submit the F10 notification (someone can do it on their behalf).","The principal contractor must prepare a construction phase plan before work starts and give every worker a site induction."],"answer":"Appoint a principal designer and principal contractor, notify HSE via F10, and have a construction phase plan and inductions in place"},"keyTerms":[{"term":"Principal contractor","definition":"The contractor appointed to plan, manage, monitor and co-ordinate health and safety in the construction phase."},{"term":"Principal designer","definition":"The designer appointed to plan, manage and co-ordinate health and safety in the pre-construction phase."},{"term":"Construction phase plan","definition":"A written plan setting out how health and safety will be managed during construction."},{"term":"F10","definition":"The form used to notify HSE of a notifiable construction project."}],"misconceptions":[{"wrong":"CDM 2015 only applies to large projects.","right":"It applies to all construction projects, including domestic ones. Only notification depends on size."},{"wrong":"Only the principal contractor is responsible for safety on site.","right":"Every duty holder, including workers, has duties, and everyone must co-operate."},{"wrong":"The principal contractor notifies HSE.","right":"The client has the duty to notify, although someone may do it on their behalf."}],"retrieval":[{"q":"Under which Act are the CDM Regulations 2015 made?","a":"The Health and Safety at Work etc. Act 1974."},{"q":"When must a principal contractor be appointed?","a":"When there is, or is likely to be, more than one contractor on the project."},{"q":"Who must prepare the construction phase plan?","a":"The principal contractor, or the contractor if there is only one."}],"specRefs":[{"board":"City & Guilds","code":"T Level Onsite Construction 603/6917/6","section":"Core: Health and safety","url":"https://www.cityandguilds.com/qualifications-and-apprenticeships/construction/construction/8711-t-level-technical-qualification-in-onsite-construction"},{"board":"HSE","code":"CDM 2015","section":"Construction (Design and Management) Regulations 2015","url":"https://www.hse.gov.uk/construction/cdm/2015/index.htm"}],"route":"tlevel","subject":"Onsite Construction"},"question_keys":["tlevel-onsite-cdm-2015:cdm1","tlevel-onsite-cdm-2015:cdm2","tlevel-onsite-cdm-2015:cdm3"],"version":"1.0"},{"course_id":"tlevel-accounting","topic_id":"tlevel-accounting-double-entry","course_title":"T Level in Accounting","title":"Double-entry bookkeeping and the trial balance","content":{"summary":"The accounting equation, debits and credits, ledger accounts and the trial balance.","objectives":["Apply the accounting equation","Record transactions using the rules of double entry","Balance off ledger accounts and prepare a trial balance","Identify errors that a trial balance does not reveal"],"explanation":["The accounting equation is assets = liabilities + capital. Every transaction changes at least two items, but the equation always balances.","Double entry records each transaction twice: a debit in one account and an equal credit in another. Debits increase assets and expenses (and drawings); credits increase liabilities, capital and income. The memory aid DEAD CLIC helps: Debit for Expenses, Assets, Drawings; Credit for Liabilities, Income, Capital.","Ledger accounts are often drawn as T-accounts, with debits on the left and credits on the right. To balance off an account, total both sides, put the difference on the smaller side as the balance carried down (c/d), and bring it down on the opposite side as the balance brought down (b/d).","A trial balance lists every ledger balance in a debit or credit column. If the double entry is arithmetically correct, the two totals agree. It is a check on the books and the starting point for preparing the income statement and statement of financial position.","A trial balance that agrees is not proof there are no errors. Errors of omission, commission, principle, original entry, reversal and compensating errors do not stop the totals agreeing."],"workedExample":{"question":"A new business: (1) the owner pays £5,000 into the business bank account; (2) buys equipment for £1,200, paying by bank; (3) buys goods for resale on credit for £800; (4) makes cash sales of £950, banked. Record the entries and prepare a trial balance.","steps":["(1) Debit Bank £5,000; credit Capital £5,000.","(2) Debit Equipment £1,200; credit Bank £1,200.","(3) Debit Purchases £800; credit Trade payables £800.","(4) Debit Bank £950; credit Sales £950.","Balance off Bank: £5,000 + £950 − £1,200 = £4,750 debit.","Debit column: Bank £4,750 + Equipment £1,200 + Purchases £800 = £6,750.","Credit column: Capital £5,000 + Trade payables £800 + Sales £950 = £6,750. The totals agree. ✓"],"answer":"Trial balance totals £6,750 debit and £6,750 credit"},"keyTerms":[{"term":"Accounting equation","definition":"Assets = liabilities + capital."},{"term":"Debit","definition":"An entry on the left of a ledger account; increases assets, expenses and drawings."},{"term":"Credit","definition":"An entry on the right of a ledger account; increases liabilities, capital and income."},{"term":"Trial balance","definition":"A list of all ledger balances used to check that total debits equal total credits."}],"misconceptions":[{"wrong":"Debit means money coming in and credit means money going out.","right":"It depends on the account. Money received is a debit in the bank account, but the matching credit goes to another account such as Sales."},{"wrong":"If the trial balance agrees, the accounts are error-free.","right":"Several types of error, such as omission or principle, leave the totals in agreement."},{"wrong":"Buying goods on credit reduces the bank balance.","right":"No money leaves the bank yet. The credit entry goes to Trade payables, a liability."}],"retrieval":[{"q":"State the accounting equation.","a":"Assets = liabilities + capital."},{"q":"What are the double entries when a business pays a supplier £300 by bank?","a":"Debit Trade payables £300; credit Bank £300."},{"q":"Name two errors a trial balance will not reveal.","a":"E.g. omission, commission, principle, original entry, reversal, compensating."}],"specRefs":[{"board":"Pearson","code":"T Level Accounting 610/0007/9","section":"Element 13 (13.4 Double entry principles and the accounting equation)","url":"https://qualifications.pearson.com/content/dam/pdf/TLevels/accounting/2022/specification-and-sample-assessment-materials/acc-specification-2026.pdf"}],"route":"tlevel","subject":"Accounting"},"question_keys":["tlevel-accounting-double-entry:de1","tlevel-accounting-double-entry:de2","tlevel-accounting-double-entry:de3"],"version":"1.0"},{"course_id":"tlevel-legal-services","topic_id":"tlevel-legal-civil-courts","course_title":"T Level in Legal Services","title":"The civil court system and track allocation","content":{"summary":"The civil courts of England and Wales, routes of appeal, and how claims are allocated to tracks.","objectives":["Describe the civil courts of first instance and the appeal courts","Name the three divisions of the High Court","Explain how claims are allocated to the four tracks","Outline pre-action conduct and alternative dispute resolution"],"explanation":["Most civil claims start in the County Court. Higher-value or more complex claims may start in the High Court, which has three divisions: the King''s Bench Division (for example contract and tort claims), the Chancery Division (for example business, property, trusts and insolvency) and the Family Division.","Appeals usually go to the next level of judge, and permission to appeal is normally needed. Above the High Court is the Court of Appeal (Civil Division), and the highest appeal court is the UK Supreme Court, which hears cases of general public importance.","Under the Civil Procedure Rules (CPR), a defended claim is allocated to a track. The small claims track is normally for claims worth up to £10,000 (lower limits apply to personal injury). The fast track is for claims up to £25,000 with a trial of no more than one day. The intermediate track, introduced in October 2023, covers many claims up to £100,000 with a trial of up to three days. More complex or higher-value claims go to the multi-track.","Before issuing a claim, parties are expected to follow pre-action conduct and any relevant pre-action protocol: exchanging information, trying to settle, and considering alternative dispute resolution (ADR) such as negotiation, mediation or arbitration. Courts can penalise unreasonable refusal to consider ADR, for example through costs.","Your specification may describe three tracks; the intermediate track was added to the CPR for most claims issued on or after 1 October 2023, so check which version your exam uses."],"workedExample":{"question":"Which track is each claim likely to be allocated to? (a) An unpaid invoice for £6,000. (b) A breach of contract claim for £18,000 needing a half-day trial. (c) A £60,000 claim with a two-day trial, one claimant and one defendant.","steps":["(a) £6,000 is not more than £10,000 and it is not a personal injury claim, so the small claims track.","(b) £18,000 is above £10,000 but not more than £25,000, and the trial will last less than a day, so the fast track.","(c) £60,000 is above £25,000 but not more than £100,000; the trial is under three days and there is one claimant against one defendant (the intermediate track allows one claimant against one or two defendants, or two claimants against one defendant), so the intermediate track."],"answer":"(a) Small claims track, (b) fast track, (c) intermediate track"},"keyTerms":[{"term":"Court of first instance","definition":"The court where a case is first heard, such as the County Court."},{"term":"Civil Procedure Rules (CPR)","definition":"The rules governing procedure in the civil courts of England and Wales."},{"term":"Track allocation","definition":"Assigning a defended claim to the small claims, fast, intermediate or multi-track."},{"term":"Alternative dispute resolution (ADR)","definition":"Ways of settling disputes outside court, such as negotiation, mediation and arbitration."}],"misconceptions":[{"wrong":"All civil cases start in the High Court.","right":"Most start in the County Court; the High Court deals with higher-value or complex claims."},{"wrong":"Track allocation depends only on the amount claimed.","right":"Value is the starting point, but the court also considers complexity, trial length, expert evidence and the parties."},{"wrong":"It is still called the Queen''s Bench Division.","right":"It became the King''s Bench Division in September 2022."}],"retrieval":[{"q":"Name the three divisions of the High Court.","a":"King''s Bench, Chancery and Family."},{"q":"What is the normal upper limit for the small claims track?","a":"£10,000 (lower for personal injury)."},{"q":"What is the highest appeal court for civil cases in the UK?","a":"The UK Supreme Court."}],"specRefs":[{"board":"Pearson","code":"T Level Legal Services 610/2226/3","section":"Element 13 (13.1.3 Hierarchy of the courts; 13.6 Civil Procedure Rules)","url":"https://qualifications.pearson.com/content/dam/pdf/TLevels/legal-services/2023/specification-and-sample-assessment-materials/leg-specification-2025.pdf"},{"board":"Ministry of Justice","code":"CPR Part 26","section":"26.9 Scope of each track","url":"https://www.justice.gov.uk/courts/procedure-rules/civil/rules/part26"}],"route":"tlevel","subject":"Legal Services"},"question_keys":["tlevel-legal-civil-courts:cc1","tlevel-legal-civil-courts:cc2","tlevel-legal-civil-courts:cc3"],"version":"1.0"},{"course_id":"cambridge-technicals","topic_id":"ctech-it-networks","course_title":"OCR Cambridge Technicals","title":"Network characteristics and IP addressing","content":{"summary":"Network models, topologies, IP addresses, subnet masks and default gateways.","objectives":["Compare peer-to-peer and client–server networks","Describe bus, star, ring and mesh topologies","Explain the role of an IP address, subnet mask and default gateway","Calculate the number of usable hosts on a subnet"],"explanation":["In a client–server network, central servers provide services such as file storage, authentication or DNS to client devices. This makes security, backup and management easier, but it costs more and the server can be a single point of failure. In a peer-to-peer network, each device shares resources directly; it is cheap and simple but harder to secure and manage.","Topology is the layout of a network. In a star, every device connects to a central switch: easy to add devices, and one cable failure only affects one device, but if the switch fails the whole network stops. A bus uses a single backbone cable; a ring passes data around a loop; a mesh links devices with many connections, giving high resilience at higher cost.","An IPv4 address, such as 192.168.1.20, identifies a device on a network. The subnet mask, such as 255.255.255.0 (or /24), shows which part of the address identifies the network and which part identifies the host.","The default gateway is the address of the router that forwards traffic to other networks, including the internet. Devices on the same subnet can communicate directly; traffic for other networks is sent to the gateway.","A subnet with h host bits has 2ʰ − 2 usable host addresses, because the all-zeros address identifies the network and the all-ones address is the broadcast address."],"workedExample":{"question":"A device has the IP address 192.168.1.20 with subnet mask 255.255.255.0. Find the network address, the broadcast address and the number of usable host addresses.","steps":["255.255.255.0 means the first three octets (24 bits) identify the network, leaving 8 host bits.","Network address: set the host bits to 0, giving 192.168.1.0.","Broadcast address: set the host bits to 1, giving 192.168.1.255.","Usable hosts = 2⁸ − 2 = 256 − 2 = 254 (192.168.1.1 to 192.168.1.254)."],"answer":"Network 192.168.1.0, broadcast 192.168.1.255, 254 usable hosts"},"keyTerms":[{"term":"Topology","definition":"The physical or logical layout of devices and connections in a network."},{"term":"Subnet mask","definition":"A value showing which part of an IP address is the network and which is the host."},{"term":"Default gateway","definition":"The router address a device sends traffic to when the destination is on another network."},{"term":"Client–server","definition":"A network model in which central servers provide services to client devices."}],"misconceptions":[{"wrong":"In a star topology, one device failing brings the whole network down.","right":"Only failure of the central switch does that; a single device or cable failure affects just that device."},{"wrong":"A /24 subnet can hold 256 devices.","right":"It has 256 addresses, but the network and broadcast addresses cannot be assigned, leaving 254."}],"retrieval":[{"q":"What is the main weakness of a star topology?","a":"If the central switch fails, the whole network fails."},{"q":"What does the default gateway do?","a":"It routes traffic to other networks, such as the internet."},{"q":"How many usable hosts does a subnet with 8 host bits have?","a":"2⁸ − 2 = 254."}],"specRefs":[{"board":"OCR","code":"Cambridge Technicals Level 3 IT","section":"Unit 1 Fundamentals of IT (LO3: 3.3 Networking characteristics)","url":"https://www.ocr.org.uk/Images/267350-fundamentals-of-it.pdf"}],"route":"level23","subject":"Cambridge Technicals"},"question_keys":["ctech-it-networks:nw1","ctech-it-networks:nw2","ctech-it-networks:nw3"],"version":"1.0"},{"course_id":"functional-skills-maths","topic_id":"gcse-maths-percentages","course_title":"Functional Skills Mathematics","title":"Percentages and percentage change","content":{"summary":"Find percentages of amounts, increase and decrease by a percentage, and work out percentage change.","objectives":["Find a percentage of an amount with and without a calculator","Use multipliers for percentage increase and decrease","Calculate percentage change and reverse percentages"],"explanation":["Per cent means ''out of 100''. 35% is 35/100 = 0.35. Converting percentages to decimals lets you use a single multiplication.","Without a calculator, build from easy pieces: 10% is ÷10, 5% is half of 10%, 1% is ÷100. For example 15% of 80 = 10% (8) + 5% (4) = 12.","A multiplier combines the original amount and the change. An increase of 12% means you keep 100% and add 12%, so multiply by 1.12. A decrease of 12% leaves 88%, so multiply by 0.88.","Percentage change = (change ÷ original) × 100. Always divide by the original value, not the new one.","Reverse percentages work backwards from the new value: if a price after a 20% increase is £60, then 1.2 × original = 60, so original = 60 ÷ 1.2 = £50."],"workedExample":{"question":"A jacket costs £64. In a sale it is reduced by 15%. What is the sale price?","steps":["A 15% decrease leaves 85% of the price.","Multiplier = 0.85.","£64 × 0.85 = £54.40."],"answer":"£54.40"},"keyTerms":[{"term":"Multiplier","definition":"The decimal you multiply by to apply a percentage change in one step, e.g. 1.05 for a 5% increase."},{"term":"Percentage change","definition":"(Change ÷ original value) × 100."},{"term":"Reverse percentage","definition":"Finding the original amount when you know the value after a percentage change."},{"term":"Compound interest","definition":"Interest calculated on the original amount plus interest already added; use multiplier to the power of the number of periods."}],"misconceptions":[{"wrong":"To undo a 20% increase, take off 20% of the new price.","right":"Divide by the multiplier (1.2). Taking 20% of the new, larger price removes too much."},{"wrong":"Percentage change divides by the new value.","right":"Always divide the change by the original value."}],"retrieval":[{"q":"What multiplier gives a 7% decrease?","a":"0.93"},{"q":"What is 15% of 80?","a":"12"},{"q":"A value rises from 40 to 50. What is the percentage increase?","a":"10 ÷ 40 × 100 = 25%"}],"specRefs":[{"board":"AQA","code":"8300","section":"R9 percentages; N12, R16 compound interest","url":"https://www.aqa.org.uk/subjects/mathematics/gcse/mathematics-8300/specification"}],"route":"level23","subject":"Functional Skills Maths","foundationFrom":"GCSE Mathematics"},"question_keys":["gcse-maths-percentages:pc1","gcse-maths-percentages:pc2","gcse-maths-percentages:pc3","gcse-maths-percentages:pc4"],"version":"1.0"},{"course_id":"functional-skills-maths","topic_id":"fs-maths-ratio","course_title":"Functional Skills Mathematics","title":"Ratio and proportion","content":{"summary":"Share amounts in a ratio, simplify ratios and scale recipes and plans.","objectives":["Simplify ratios","Share an amount in a given ratio","Solve direct proportion problems in real contexts"],"explanation":["A ratio compares quantities. Simplify by dividing all parts by a common factor: 12:8 = 3:2.","To share in a ratio: add the parts, find the value of one part, then multiply. £60 in the ratio 2:3 → 5 parts, 1 part = £12, so £24 and £36.","Direct proportion: if 4 tickets cost £18, one ticket costs £4.50, so 7 cost £31.50. Find one first (the unitary method)."],"workedExample":{"question":"A recipe for 4 people uses 300 g of flour. How much for 10 people?","steps":["For 1 person: 300 ÷ 4 = 75 g.","For 10 people: 75 × 10 = 750 g."],"answer":"750 g"},"keyTerms":[{"term":"Ratio","definition":"A comparison of two or more quantities, e.g. 2:3."},{"term":"Unitary method","definition":"Finding the value of one unit first, then scaling."},{"term":"Direct proportion","definition":"When one quantity doubles, the other doubles too."}],"misconceptions":[{"wrong":"Sharing £60 in the ratio 2:3 gives £20 and £30.","right":"There are 5 parts; one part is £12, giving £24 and £36."}],"retrieval":[{"q":"Simplify 15:10.","a":"3:2"},{"q":"Share 40 in the ratio 1:3.","a":"10 and 30"},{"q":"3 pens cost £2.40. How much do 5 cost?","a":"£4.00"}],"specRefs":[{"board":"DfE","code":"Functional Skills Maths","section":"Using numbers: ratio and direct proportion (L1), ratio, direct and inverse proportion (L2)","url":"https://www.gov.uk/government/publications/functional-skills-subject-content-mathematics"}],"route":"level23","subject":"Functional Skills Maths"},"question_keys":["fs-maths-ratio:ra1","fs-maths-ratio:ra2"],"version":"1.1"},{"course_id":"functional-skills-english","topic_id":"gcse-englang-language-analysis","course_title":"Functional Skills English","title":"Analysing language","content":{"summary":"Explain how writers use words, phrases and techniques to create effects on the reader.","objectives":["Select short, precise quotations","Identify language features using accurate terminology","Explain the effect of language choices on the reader"],"explanation":["Examiners reward explanation of effect more than spotting techniques. Naming a metaphor earns little unless you explain what it suggests and why the writer chose it.","Use short quotations, often a single word or phrase, and zoom in on connotations: what ideas, feelings or images does the word bring to mind?","A useful structure is: point about the writer''s method → embedded quotation → explanation of effect → link to the writer''s wider purpose.","Consider word classes too: a verb can show how something moves or acts, adjectives can build atmosphere, and adverbs can reveal attitude."],"workedExample":{"question":"Analyse: ''The wind clawed at the windows, desperate to get in.''","steps":["Method: personification. The wind is given a human feeling (''desperate''), and the verb ''clawed'' adds animal-like imagery.","Zoom in: ''clawed'' suggests sharp, violent, animal movement.","Effect: the weather feels threatening and alive; ''desperate'' adds urgency and makes the house feel under attack.","Purpose: builds tension and a sense of danger for the reader."],"answer":"A strong answer links the verb ''clawed'' and the adjective ''desperate'' to a mood of threat and tension."},"keyTerms":[{"term":"Connotation","definition":"An idea or feeling a word suggests beyond its literal meaning."},{"term":"Personification","definition":"Giving human qualities to something non-human."},{"term":"Semantic field","definition":"A group of words linked by a common topic, e.g. words linked to war."},{"term":"Embedded quotation","definition":"A short quotation woven into your own sentence."}],"misconceptions":[{"wrong":"''This makes the reader want to read on'' is a good explanation.","right":"Be specific: say what the reader feels or imagines, and why that word creates it."},{"wrong":"Long quotations show more evidence.","right":"Short, precise quotations let you analyse individual word choices."}],"retrieval":[{"q":"What is a connotation?","a":"An idea or feeling associated with a word beyond its literal meaning."},{"q":"Name the four parts of a strong analytical paragraph.","a":"Method, quotation, effect, link to purpose."},{"q":"Why is naming a technique not enough?","a":"Marks are for explaining the effect of the choice, not labelling it."}],"specRefs":[{"board":"AQA","code":"8700","section":"AO2 — Paper 1 and Paper 2, Section A (Reading)","url":"https://www.aqa.org.uk/subjects/english/gcse/english-language-8700/specification"}],"route":"level23","subject":"Functional Skills English","foundationFrom":"GCSE English Language"},"question_keys":["gcse-englang-language-analysis:la1","gcse-englang-language-analysis:la2","gcse-englang-language-analysis:la3"],"version":"1.1"},{"course_id":"core-maths","topic_id":"core-maths-estimation","course_title":"Core Maths (Level 3)","title":"Estimation and Fermi problems","content":{"summary":"Make sensible assumptions to estimate quantities and judge whether answers are reasonable.","objectives":["Break a large estimation problem into smaller steps","State and justify assumptions","Judge the reasonableness of an estimate"],"explanation":["A Fermi problem asks for a reasonable estimate when exact data is not available, for example ''How many litres of water does a school use in a day?''","Break the problem into parts you can estimate: number of people, uses per person, amount per use.","Round to convenient numbers and state each assumption clearly. Marks usually reward sensible reasoning, not a single ''correct'' answer.","Finally, sense-check: is the answer the right order of magnitude? Could a small change in an assumption change it a lot?"],"workedExample":{"question":"Estimate how many hours a Year 12 student spends on a phone in a year.","steps":["Assume about 4 hours per day (stated assumption).","4 × 365 = 1,460, which rounds to about 1,500 hours.","Sense-check: about 17% of the year, which is plausible."],"answer":"Roughly 1,500 hours (depending on assumptions)"},"keyTerms":[{"term":"Fermi estimate","definition":"A rough estimate built from reasoned assumptions."},{"term":"Order of magnitude","definition":"The power of ten when a number is written in standard form, e.g. 3,800 = 3.8 × 10³ has order of magnitude 10³."},{"term":"Assumption","definition":"A value or condition accepted as true to make a problem solvable."}],"misconceptions":[{"wrong":"There is one correct answer to an estimation question.","right":"Different sensible assumptions lead to different, equally valid estimates."}],"retrieval":[{"q":"What is a Fermi problem?","a":"An estimation problem solved by reasoned assumptions."},{"q":"What should you always state in an estimate?","a":"Your assumptions."},{"q":"What is the order of magnitude of 3,800?","a":"10³ (thousands)"}],"specRefs":[{"board":"AQA","code":"1350","section":"3.3 Estimation (Fermi estimation)"}],"route":"level23","subject":"Core Maths"},"question_keys":["core-maths-estimation:fe1"],"version":"1.1"},{"course_id":"epq","topic_id":"epq-planning","course_title":"Extended Project Qualification (EPQ)","title":"Planning an EPQ and referencing sources","content":{"summary":"Choose a focused question, plan milestones and record research properly.","objectives":["Write a focused, researchable project question","Plan milestones and keep a production log","Evaluate and reference sources consistently"],"explanation":["A strong EPQ question is focused and debatable, e.g. ''To what extent…?'' rather than ''Everything about…''.","Plan backwards from your deadline with milestones for research, drafting, review and your presentation. Record decisions and changes in your production log.","Evaluate sources for authority, accuracy, purpose, currency and bias. Use a wide range, including academic sources where possible.","Pick one referencing style (for example Harvard) and use it consistently. Keep track of references as you go rather than at the end."],"workedExample":null,"keyTerms":[{"term":"Production log","definition":"The record of your planning, decisions and reflections through the project."},{"term":"Referencing","definition":"Acknowledging the sources you use in a consistent format."},{"term":"Literature review","definition":"A summary and evaluation of existing research on your topic."},{"term":"Plagiarism","definition":"Presenting someone else''s work or ideas as your own."}],"misconceptions":[{"wrong":"A broad question gives more to write about.","right":"A focused question allows deeper analysis and a clear conclusion."},{"wrong":"The production log is filled in at the end.","right":"It should be kept up to date throughout the project."}],"retrieval":[{"q":"What makes a good EPQ question?","a":"It is focused, researchable and debatable."},{"q":"Name three criteria for evaluating a source.","a":"E.g. authority, accuracy, purpose, currency, bias."},{"q":"What is a production log?","a":"A record of planning, decisions and reflection across the project."}],"specRefs":[{"board":"AQA","code":"7993","section":"AO1 Manage, AO2 Use resources","url":"https://www.aqa.org.uk/subjects/projects/project-qualifications/epq-7993/specification"}],"route":"level23","subject":"Extended Project"},"question_keys":["epq-planning:ep1"],"version":"1.0"},{"course_id":"applied-general","topic_id":"applied-general-break-even","course_title":"Applied General and other Level 3 vocational qualifications","title":"Break-even analysis","content":{"summary":"Fixed and variable costs, contribution, break-even output and margin of safety.","objectives":["Distinguish between fixed, variable, semi-variable and total costs","Calculate contribution per unit and break-even output","Calculate and interpret the margin of safety","Evaluate the uses and limitations of break-even analysis"],"explanation":["Fixed costs, such as rent and salaries, do not change with output in the short run. Variable costs, such as raw materials, rise with each unit produced. Semi-variable costs have a fixed part and a variable part, such as a phone contract with a line rental and a call charge. Total cost = fixed costs + total variable costs.","Contribution per unit = selling price − variable cost per unit. It is the amount each unit sold contributes towards covering fixed costs and then making profit.","Break-even output = fixed costs ÷ contribution per unit. At break-even, total revenue equals total cost, so the business makes neither a profit nor a loss.","The margin of safety is the amount by which actual or planned sales exceed break-even: margin of safety = actual output − break-even output. It shows how far sales could fall before the business makes a loss. Profit = margin of safety × contribution per unit.","Break-even analysis is quick and useful for planning, pricing and supporting loan applications. However, it assumes that all output is sold at one price and that costs are fixed and linear, which is rarely true in practice, so conclusions must be treated with care."],"workedExample":{"question":"A business has fixed costs of £12,000 a month. It sells each product for £25, and the variable cost per unit is £10. It expects to sell 1,100 units a month. Find the break-even output, the margin of safety and the profit.","steps":["Contribution per unit = £25 − £10 = £15.","Break-even output = £12,000 ÷ £15 = 800 units.","Margin of safety = 1,100 − 800 = 300 units (300 × £25 = £7,500 of revenue).","Profit = 300 × £15 = £4,500.","Check: revenue 1,100 × £25 = £27,500; total cost £12,000 + 1,100 × £10 = £23,000; profit £4,500. ✓"],"answer":"Break-even at 800 units, margin of safety 300 units, profit £4,500"},"keyTerms":[{"term":"Fixed costs","definition":"Costs that do not change with output in the short run."},{"term":"Contribution per unit","definition":"Selling price minus variable cost per unit."},{"term":"Break-even point","definition":"The output at which total revenue equals total cost: no profit and no loss."},{"term":"Margin of safety","definition":"The amount by which actual sales exceed break-even sales."}],"misconceptions":[{"wrong":"Break-even output = fixed costs ÷ selling price.","right":"Divide fixed costs by contribution per unit (price minus variable cost), not by price."},{"wrong":"Fixed costs never change.","right":"They do not change with output in the short run, but they can change over time, for example when rent rises."},{"wrong":"Contribution is the same as profit.","right":"Contribution first covers fixed costs. Only contribution beyond break-even is profit."}],"retrieval":[{"q":"Write the formula for break-even output.","a":"Fixed costs ÷ contribution per unit."},{"q":"What happens to break-even output if the selling price rises and costs stay the same?","a":"It falls, because contribution per unit increases."},{"q":"What does the margin of safety show?","a":"How far sales could fall before the business makes a loss."}],"specRefs":[{"board":"Pearson","code":"BTEC Nationals Business (2016)","section":"Unit 3 Personal and Business Finance (E2 Break-even analysis)","url":"https://qualifications.pearson.com/content/dam/pdf/BTEC-Nationals/Business/2016/specification-and-sample-assessments/btecnationals-bus-exdip-spec.pdf"},{"board":"AQA","code":"Applied General Business 1830","section":"Unit 1 Financial planning and analysis","url":"https://www.aqa.org.uk/subjects/business/applied-general/business-1830/specification"}],"route":"level23","subject":"Applied General"},"question_keys":["applied-general-break-even:be1","applied-general-break-even:be2","applied-general-break-even:be3"],"version":"1.0"}]'::jsonb) on conflict(course_id,topic_id) do update set course_title=excluded.course_title,title=excluded.title,content=excluded.content,question_keys=excluded.question_keys,version=excluded.version;
with registry(course_id,title,route,subject) as(values ('gcse-maths','GCSE Mathematics','gcse','Mathematics'),('gcse-english-language','GCSE English Language','gcse','English Language'),('gcse-english-literature','GCSE English Literature','gcse','English Literature'),('gcse-biology','GCSE Biology','gcse','Biology'),('gcse-chemistry','GCSE Chemistry','gcse','Chemistry'),('gcse-physics','GCSE Physics','gcse','Physics'),('gcse-combined-science','GCSE Combined Science','gcse','Combined Science'),('gcse-history','GCSE History','gcse','History'),('gcse-geography','GCSE Geography','gcse','Geography'),('gcse-computer-science','GCSE Computer Science','gcse','Computer Science'),('alevel-maths','A level Mathematics','alevel','Mathematics'),('alevel-further-maths','A level Further Mathematics','alevel','Further Mathematics'),('alevel-biology','A level Biology','alevel','Biology'),('alevel-chemistry','A level Chemistry','alevel','Chemistry'),('alevel-physics','A level Physics','alevel','Physics'),('alevel-psychology','A level Psychology','alevel','Psychology'),('alevel-english-literature','A level English Literature','alevel','English Literature'),('alevel-history','A level History','alevel','History'),('alevel-economics','A level Economics','alevel','Economics'),('alevel-computer-science','A level Computer Science','alevel','Computer Science'),('btec-applied-science','BTEC Applied Science','btec','Applied Science'),('btec-business','BTEC Business','btec','Business'),('btec-health-social-care','BTEC Health and Social Care','btec','Health and Social Care'),('btec-it','BTEC Information Technology','btec','Information Technology'),('btec-sport','BTEC Sport','btec','Sport'),('btec-engineering','BTEC Engineering','btec','Engineering'),('btec-creative-media','BTEC Creative Media','btec','Creative Media'),('tlevel-digital-production','T Level in Digital Software Development','tlevel','Digital Software Development'),('tlevel-digital-support','T Level in Digital Support and Security','tlevel','Digital Support and Security'),('tlevel-health','T Level in Health','tlevel','Health'),('tlevel-healthcare-science','T Level in Healthcare Science','tlevel','Healthcare Science'),('tlevel-science','T Level in Science','tlevel','Science'),('tlevel-education-early-years','T Level in Education and Early Years','tlevel','Education and Early Years'),('tlevel-construction-design','T Level in Design, Surveying and Planning for Construction','tlevel','Design, Surveying and Planning for Construction'),('tlevel-onsite-construction','T Level in Onsite Construction','tlevel','Onsite Construction'),('tlevel-accounting','T Level in Accounting','tlevel','Accounting'),('tlevel-legal-services','T Level in Legal Services','tlevel','Legal Services'),('cambridge-technicals','OCR Cambridge Technicals','level23','Cambridge Technicals'),('functional-skills-maths','Functional Skills Mathematics','level23','Functional Skills Maths'),('functional-skills-english','Functional Skills English','level23','Functional Skills English'),('core-maths','Core Maths (Level 3)','level23','Core Maths'),('epq','Extended Project Qualification (EPQ)','level23','Extended Project'),('applied-general','Applied General and other Level 3 vocational qualifications','level23','Applied General')),
groups as(select b.course_id,q.topic,array_agg(b.key order by b.key) as keys,bool_or(not q.publish_ready) as draft,
 min(r.title) as course_title,min(r.route) as route,min(r.subject) as subject,
 jsonb_agg(jsonb_build_object('prompt',b.prompt,'answer',b.options->>b.answer,'explain',b.explain,'source',q.source,'licence',q.licence) order by b.key) as examples
 from private.study_question_bank b join public.bank_questions q on b.key='qb-'||q.id join registry r on r.course_id=b.course_id
 where q.review_status not in('retired','flagged_needs_fix') group by b.course_id,q.topic)
insert into public.subject_quest_catalogue(course_id,topic_id,course_title,title,content,question_keys,version)
select course_id,left(course_id||'-'||regexp_replace(lower(topic),'[^a-z0-9]+','-','g'),100)||'-'||substr(md5(topic),1,8),course_title,topic,
 jsonb_build_object('summary','Review worked examples for '||topic||', then practise retrieving the methods and facts.',
 'objectives',jsonb_build_array('Study the worked examples.','Explain the method in your own words.','Complete two scored retrieval rounds.'),
 'explanation',(select jsonb_agg('Example: '||(x->>'prompt')||E'\n\nAnswer: '||(x->>'answer')||E'\n\n'||(x->>'explain')) from(select x from jsonb_array_elements(examples) with ordinality e(x,n) where n<=8)s),
 'workedExample',null,'keyTerms','[]'::jsonb,'misconceptions','[]'::jsonb,'retrieval','[]'::jsonb,'route',route,'subject',subject,'draftPractice',draft,
 'sources',(select jsonb_agg(distinct jsonb_build_object('source',x->>'source','licence',x->>'licence')) from jsonb_array_elements(examples)x)),
 keys,'question-bank-v1' from groups
on conflict(course_id,topic_id) do update set course_title=excluded.course_title,title=excluded.title,content=excluded.content,question_keys=excluded.question_keys,version=excluded.version;
commit;
